NAME = 'DaOT1871NT1907: Danish OT1871 + NT1907 with original orthography'
BOOK = 'I Kings'

CHAPTERS = {
    1: {
        1: 'Og Kong David var gammel, kommen til Aars, og de dækkede ham til med Klæder, men han blev ikke varm.',
        2: 'Da sagde hans Tjenere til ham: Lad dem oplede til vor Herre Kongen en ung Pige, en Jomfru, at hun kan staa for Kongens Ansigt og pleje ham og ligge i din Arm, og min Herre Kongen kan blive varm.',
        3: 'Og de ledte efter en dejlig ung Pige inden alt Israels Landemærke, og de fandt Abisag, den sunamitiske, og de førte hende til Kongen.',
        4: 'Og Pigen var over maade dejlig, og hun plejede Kongen og tjente ham; men Kongen kendte hende ikke.',
        5: 'Og Adonia, Hagiths Søn, op højede sig selv og sagde: Jeg vil være Konge; og han skaffede sig Vogne og Ryttere og halvtredsindstyve Mænd, som løb foran ham',
        6: 'Og hans Fader havde ikke bedrøvet ham i sine Dage ved at sige: Hvorfor gør du saaledes? og han var saare dejlig af Skikkelse, og hans Moder havde født ham næst efter Absalom.',
        7: 'Og han førte Tale med Joab, Zerujas Søn, og med Præsten Abjathar, og de understøttede Adonia.',
        8: 'Men Zadok, Præsten, og Benaja, Jojadas Søn, og Nathan, Profeten, og Simei og Rei og de vældige, som David havde, de vare ikke med Adonia.',
        9: 'Og Adonia slagtede stort Kvæg og smaat Kvæg og fedt Kvæg ved Soheleths Sten, som ligger ved En-Rogel, og han indbød alle sine Brødre, Kongens Sønner, og alle Judas Mænd, Kongens Tjenere.',
        10: 'Men Nathan, Profeten, og Benaja og de vældige og Salomo, sin Broder, indbød han ikke.',
        11: 'Da talede Nathan til Bathseba, Salomos Moder, sigende: Har du ikke hørt, at Adonia, Hagiths Søn, er bleven Konge, og vor Herre David ved det ikke?',
        12: 'Saa gak nu, kære, jeg vil raade dig et Raad, at du skal redde dit Liv og din Søn Salomos Liv.',
        13: 'Gak hen og træd ind til Kong David, og du skal sige til ham: Du, min Herre Konge, har du ikke tilsvoret din Tjenestekvinde og sagt: Din Søn Salomo skal være Konge efter mig, og han skal sidde paa min Trone; hvorfor er da Adonia bleven Konge?',
        14: 'Se, naar du endnu taler der med Kongen, vil og jeg komme efter dig og fuldende din Tale.',
        15: 'Og Bathseba kom ind til Kongen i Kammeret; og Kongen var saare gammel, og Abisag, den sunamitiske, tjente Kongen.',
        16: 'Og Bathseba nejede og bøjede sig dybt for Kongen; da sagde Kongen: Hvad fattes dig?',
        17: 'Og hun sagde til ham: Min Herre! du har tilsvoret din Tjenestekvinde ved Herren din Gud: Din Søn Salomo skal blive Konge efter mig, og han skal sidde paa min Trone.',
        18: 'Men nu, se, Adonia er bleven Konge, og nu, min Herre Konge, du ved det ikke.',
        19: 'Og han har slagtet Øksne og fedt Kvæg og Faar i Mangfoldighed, og han har indbudt alle Kongens Sønner og Abjathar, Præsten, og Joab, Stridshøvedsmanden; men han har ikke indbudt din Tjener Salomo.',
        20: 'Men du, min Herre Konge, al Israels Øjne se paa dig, at du skal give dem til Kende, hvo der skal sidde paa min Herre Kongens Trone efter ham.',
        21: 'Ellers sker det, naar min Herre Kongen ligger med sine Fædre, at jeg og min Søn Salomo maa være som Syndere.',
        22: 'Og se, da hun endnu talede med Kongen, da kom Profeten Nathan.',
        23: 'Og de gave Kongen det til Kende og sagde: Se, der er Profeten Nathan; og der han kom for Kongens Ansigt, da bøjede han sig ned for Kongen paa sit Ansigt til Jorden.',
        24: 'Og Nathan sagde: Min Herre Konge, har du sagt: Adonia skal være Konge efter mig, og han skal sidde paa min Trone?',
        25: 'Thi han gik ned i Dag og slagtede Øksne og fedt Kvæg og Faar i Mangfoldighed, og han indbød alle Kongens Sønner og Høvedsmændene for Hæren og Abjathar, Præsten, og se, de æde og de drikke for hans Ansigt, og de sige: Kong Adonia leve!',
        26: 'Men mig, som er din Tjener, og Zadok, Præsten, og Benaja, Jojadas Søn, og Salomo, din Tjener, indbød han ikke.',
        27: 'Mon denne Sag skulde være sket af min Herre Kongen? og du lod din Tjener ikke vide, hvo der skal sidde paa min Herre Kongens Trone efter ham.',
        28: 'Og Kong David svarede og sagde: Kalder Bathseba til mig; og hun kom for Kongen og stod for Kongens Ansigt.',
        29: 'Da svor Kongen og sagde: Saa vist som Herren lever, han som har forløst min Sjæl af al Angest:',
        30: 'Ligesom jeg har tilsvoret dig ved Herren Israels Gud og sagt, at Salomo, din Søn, skal være Konge efter mig, og han skal sidde paa min Trone i mit Sted, saaledes vil jeg gøre paa denne Dag.',
        31: 'Da bøjede Bathseba sig med Ansigtet til Jorden og kastede sig ned for Kongen, og hun sagde: Min Herre, Kong David, leve i Evighed!',
        32: 'Og Kong David sagde: Kalder mig Zadok, Præsten, og Nathan, Profeten, og Benaja, Jojadas Søn; og de kom ind for Kongens Ansigt.',
        33: 'Da sagde Kongen til dem: Tager med eder eders Herres Tjenere, og lader min Søn Salomo ride paa den Mulæselinde, som hører mig til, og fører ham ned til Gihon.',
        34: 'Og Zadok, Præsten, og Nathan, Profeten, skulle der salve ham til Konge over Israel; og I skulle blæse i Trompeten og sige: Kong Salomo leve!',
        35: 'Og drager op efter ham, saa skal han komme og sidde paa min Trone, og han skal være Konge i mit Sted; thi jeg har budet ham at være Fyrste over Israel og over Juda.',
        36: 'Da svarede Benaja, Jojadas Søn, Kongen og sagde: Amen! saa sige Herren, min Herre Kongens Gud:',
        37: 'Saasom Herren har været med min Herre Kongen, saa være han med Salomo, og gøre hans Trone større end min Herres, Kong Davids Trone!',
        38: 'Da gik Zadok, Præsten, og Nathan, Profeten, og Benaja, Jojadas Søn, og de Krethi og de Plethi ned og satte Salomo paa Kong Davids Mulæselinde, og de førte ham til Gihon.',
        39: 'Og Zadok, Præsten, tog Oliehornet af Paulunet og salvede Salomo; og de blæste i Trompeten, og alt Folket sagde: Kong Salomo leve!',
        40: 'Og alt Folket drog op efter ham, og Folket blæste paa Fløjter og glædede sig med en stor Glæde, saa at Jorden revnede af deres Skrig.',
        41: 'Og Adonia hørte det, og alle de indbudne, som vare hos ham, og de havde endt Maaltidet; og Joab hørte Trompetens Lyd og sagde: Hvorfor det Raab i den støjende Stad?',
        42: 'Der han endnu talede, se, da kom Jonathan, Præsten Abjathars Søn, og Adonia sagde: Kom, thi du er en duelig Mand og fører et godt Budskab.',
        43: 'Og Jonathan svarede og sagde til Adonia: Ja, vor Herre, Kong David, har gjort Salomo til Konge.',
        44: 'Og Kongen sendte Zadok, Præsten, og Nathan, Profeten, og Benaja, Jojadas Søn, og de Krethi og de Plethi med ham, og de lode ham ride paa Kongens Mulæselinde.',
        45: 'Og Zadok, Præsten, og Nathan, Profeten, salvede ham til Konge i Gihon og droge derfra glade op, saa at Staden er sat i Bevægelse derved; det er det Raab, som I have hørt.',
        46: 'Dertilmed sidder Salomo paa den kongelige Trone.',
        47: 'Og Kongens Tjenere kom ogsaa at velsigne vor Herre, Kong David, og sagde: Din Gud gøre Salomos Navn bedre end dit Navn og gøre hans Trone større end din Trone! og Kongen tilbad paa Sengen.',
        48: 'Og Kongen sagde ogsaa saaledes: Lovet være Herren, Israels Gud, som i Dag har givet en, som sidder paa min Trone, at mine Øjne se det!',
        49: 'Da bleve alle, som vare indbudne af Adonia, forfærdede og stode op; og de gik hver sin Vej.',
        50: 'Og Adonia frygtede for Salomos Ansigt, og han stod op og gik bort og tog fat paa Alterets Horn.',
        51: 'Og det blev Salomo kundgjort og sagt: Se, Adonia frygter for Kong Salomo, og se, han tager fat paa Alterets Horn og siger: Kong Salomo skal sværge mig paa denne Dag, at han ikke vil dræbe sin Tjener med Sværd.',
        52: 'Og Salomo sagde: Dersom han vil være en redelig Mand, skal der ikke falde et af hans Haar paa Jorden; men om der bliver fundet ondt hos ham, da skal han dø.',
        53: 'Og Kong Salomo sendte hen, og de hentede ham ned fra Alteret, og han kom og bøjede sig ned for Kong Salomo; og Salomo sagde til ham: Gak til dit Hus.',
    },
    2: {
        1: 'Og der Davids Dage kom nær til, at han skulde dø, da bød han sin Søn Salomo og sagde:',
        2: 'Jeg gaar bort ad al Jordens Vej, saa vær frimodig og vær en Mand,',
        3: 'og tag Vare paa, hvad Herren din Gud vil have varetaget, at du vandrer i hans Veje og holder hans Skikke, hans Bud og hans Befalinger og hans Vidnesbyrd efter det, som er skrevet i Mose Lov, at du kan handle viselig i alt det, du gør, og i alt det, du vender dig til,',
        4: 'paa det Herren skal stadfæste sit Ord, som han talede over mig og sagde: Dersom dine Børn bevare deres Vej, at vandre for mit Ansigt i Sandhed, af deres ganske Hjerte og af deres ganske Sjæl, da skal, sagde han, dig ikke fattes en Mand paa Israels Stol.',
        5: 'Og du ved ogsaa, hvad Joab, Zerujas Søn, gjorde ved mig, hvad han gjorde ved de to Stridshøvedsmænd i Israel, ved Abner, Ners Søn, og ved Amasa, Jethers Søn, som han slog ihjel, og udøste Krigsblod under Fred, og kom Krigsblod paa sit Bælte, som var om hans Lænder, og paa sine Sko, som vare paa hans Fødder.',
        6: 'Og du skal gøre efter din Visdom, at du ikke lader hans graa Haar nedfare til Graven med Fred.',
        7: 'Men du skal gøre Miskundhed mod Gileaditeren Barsillajs Sønner, og de skulle være iblandt dem, som æde ved dit Bord; thi saaledes holdt de sig nær til mig, der jeg flyede for Absalom, din Broder.',
        8: 'Og se, du har hos dig Benjaminiten Simei, Geras Søn, fra Bahurim, som bandede mig med en gruelig Forbandelse, paa den Dag jeg gik til Mahanaim; men han kom ned imod mig til Jordanen, og jeg svor ham ved Herren og sagde: Jeg vil ikke slaa dig ihjel med Sværdet.',
        9: 'Men nu, du skal ikke holde ham uskyldig; thi du er en viis Mand, og du ved, hvad du skal gøre ved ham, saa at du lader hans graa Haar nedfare med Blod til Graven.',
        10: 'Saa laa David med sine Fædre og blev begraven i Davids Stad.',
        11: 'Og de Dage, som David var Koige over Israel, vare fyrretyve Aar; han var Konge i Hebron syv Aar og var Konge i Jerusalem tre og tredive Aar.',
        12: 'Og Salomo sad paa sin Faders, Davids Trone, og hans Rige blev saare fast.',
        13: 'Og Adonia, Hagiths Søn, kom ind til Bathseba, Salomos Moder, og hun sagde: Kommer du med Fred? og han sagde: Med Fred.',
        14: 'Da sagde han: Jeg har et Ord til dig; og hun sagde: Tal.',
        15: 'Og han sagde: Du ved, at Riget var mit, og al Israel havde vendt deres Ansigt til mig, at jeg skulde være Konge; men Riget er fravendt mig og blevet min Broders, thi det er blevet hans af Herren.',
        16: 'Og nu begærer jeg en Begæring af dig, du ville ikke afvise mig; men hun sagde til ham: Tal.',
        17: 'Da sagde han: Kære, tal til Kong Salomo, thi han afviser dig ikke, at han vil give mig Abisag, den sunamitiske, til Hustru.',
        18: 'Og Bathseba sagde: Godt; jeg vil tale for dig til Kongen.',
        19: 'Og Bathseba kom til Kong Salomo, at tale med ham for Adonia, og Kongen stod op imod hende og bøjede sig ned for hende, og satte sig paa sin Stol, og man satte en Stol til Kongens Moder, og hun sad ved hans højre Side.',
        20: 'Og hun sagde: Jeg begærer en liden Begæring af dig, du ville ikke afvise mig; Kongen sagde til hende: Begær, min Moder, thi jeg vil ikke afvise dig.',
        21: 'Og hun sagde: Lad Abisag, den sunamitiske, gives din Broder Adonia til Hustru.',
        22: 'Da svarede Kong Salomo og sagde til sin Moder: Men hvorfor begærer du Abisag, den sunamitiske, til Adonia? begær og Riget for ham, thi han er min Broder, ældre end jeg, og for Abjathar, Præsten, og Joab, Zerujas Søn.',
        23: 'Og Kong Salomo svor ved Herren og sagde: Gud gøre mig nu og fremdeles saa og saa! Adonia skal have talt det Ord imod sit Liv.',
        24: 'Og nu, saa vist som Herren lever, som har stadfæstet mig og ladet mig sidde paa min Fader Davids Trone, og som har givet mig et Hus, som han sagde: Da skal Adonia lide Døden i Dag.',
        25: 'Og Kong Salomo sendte ved Benaja, Jojadas Søns, Haand, og denne faldt an paa ham, saa at han døde.',
        26: 'Og Kongen sagde til Abjathar, Præsten: Gak til din Ager i Anathoth, thi du er en Dødens Mand; men jeg vil ikke slaa dig ihjel denne Dag, fordi du har baaret den Herre Herres Ark for Davids, min Faders, Ansigt, og fordi du har lidt Trængsel i alt, hvori min Fader har lidt Trængsel.',
        27: 'Saa udstødte Salomo Abjathar fra at være Herrens Præst, for at opfylde Herrens Ord, som han havde talt over Elis Hus i Silo.',
        28: 'Og der dette Rygte kom for Joab (thi Joab havde holdt med Adonia, men havde ikke holdt med Absalom), da flyede Joab til Herrens Paulun og tog fat paa Alterets Horn.',
        29: 'Og det blev Kong Salomo tilkendegivet, at Joab var flyet til Herrens Paulun, og se, han stod ved Alteret; da sendte Salomo Benaja, Jojadas Søn, hen og sagde: Gak, fald an paa ham.',
        30: 'Og der Benaja kom til Herrens Paulun, da sagde han til ham: Saa siger Kongen: Gak ud; og han sagde: Nej, thi her vil jeg dø; og Benaja førte Svar tilbage til Kongen og sagde: Saa har Joab talt, og saa har han svaret mig.',
        31: 'Da sagde Kongen til ham: Gør, saaledes som han har talt, og fald an paa ham og begrav ham; og du skal bortskaffe det uskyldige Blod, som Joab har udøst, fra mig og fra min Faders Hus.',
        32: 'Og Herren skal lade Blodet komme tilbage paa hans Hoved, fordi han faldt an paa to Mænd, som vare retfærdigere og bedre end han, og slog dem ihjel med Sværdet, og min Fader David vidste det ikke, nemlig Abner, Ners Søn, Stridshøvedsmand over Israel, og Amasa, Jethers Søn, Stridshøvedsmand over Juda,',
        33: 'at deres Blod skal komme tilbage paa Joabs Hoved og paa hans Sæds Hoved evindelig; men David og hans Sæd og hans Hus og hans Trone skal have Fred af Herren indtil evig Tid.',
        34: 'Og Benaja, Jojadas Søn, gik op og faldt an paa ham og dræbte ham; og han blev begraven i sit Hus i Ørken.',
        35: 'Og Kongen satte Benaja, Jojadas Søn, i hans Sted over Hæren, og Kongen satte Zadok, Præsten, i Abjathars Sted.',
        36: 'Og Kongen sendte hen og lod kalde Simei og sagde til ham: Byg dig et Hus i Jerusalem, og bo der, og gak ikke der ud fra hid eller did.',
        37: 'Thi det skal ske, paa hvilken Dag du gaar ud og gaar over Kedrons Bæk, da vid vist, at du skal dø; dit Blod skal være paa dit Hoved.',
        38: 'Og Simei sagde til Kongen: Det Ord er godt; ligesom min Herre Kongen har talt, saa skal din Tjener gøre. Saa boede Simei i Jerusalem mange Dage.',
        39: 'Og det skete, der tre Aar vare til Ende, at to af Simeis Tjenere flyede til Akis, Maekas Søn, Kongen i Gath; og de gave Simei det til Kende, sigende se, dine Tjenere ere i Gath.',
        40: 'Saa gjorde Simei sig rede og sadlede sit Asen og drog til Gath til Akis at oplede sine Tjenere; og Simei drog hen og førte sine Tjenere fra Gath.',
        41: 'Og det blev Salomo tilkendegivet, at Simei var dragen fra Jerusalem til Gath og var kommen tilbage.',
        42: 'Og Kongen sendte hen og lod Simei kalde og sagde til ham: Har jeg ikke besvoret dig ved Herren og vidnet for dig og sagt: Paa hvilken Dag du gaar ud og gaar hid eller did, skal du vist vide, at du skal dø? og du sagde til mig: Det Ord er godt, som jeg har hørt.',
        43: 'Hvorfor har du da ikke holdt Herrens Ed og det Bud, som jeg bød dig?',
        44: 'Og Kongen sagde til Simei: Du ved al den Ondskab, som dit Hjerte er sig bevidst, hvilken du gjorde min Fader David, og Herren har ladet din Ondskab komme tilbage paa dit Hoved.',
        45: 'Men Kong Salomo er velsignet, og Davids Trone skal være fast for Herrens Ansigt til evig Tid.',
        46: 'Saa bød Kongen Benaja, Jojadas Søn, og han gik ud og faldt an paa ham, og han døde. Og Riget blev befæstet i Salomos Haand.',
    },
    3: {
        1: 'Og Salomo besvogrede sig med Farao, Kongen af Ægypten, og tog Faraos Datter og førte hende ind i Davids Stad, indtil han havde fuldendt at bygge sit Hus og Herrens Hus og Jerusalems Mur trindt omkring;',
        2: 'ikkun at Folket ofrede paa Højene; thi der var ikke bygget et Hus til Herrens Navn indtil disse Dage.',
        3: 'Men Salomo elskede Herren og vandrede efter Davids sin Faders Skikke, kun at han ofrede og gjorde Røgelse paa Højene.',
        4: 'Og Kongen gik til Gibeon for at ofre der, thi der var den store Høj, og Salomo ofrede tusinde Brændofre paa dette Alter.',
        5: 'Herren aabenbarede sig for Salomo i Gibeon om Natten i en Drøm, og Gud sagde: Begær, hvad jeg skal give dig.',
        6: 'Og Salomo sagde: Du har gjort stor Miskundhed imod din Tjener David, min Fader, ligesom han og vandrede for dit Ansigt i Sandhed og i Retfærdighed og i Hjertets Oprigtighed imod dig; og du har bevaret ham denne store Miskundhed og har givet ham en Søn, som sidder paa hans Trone, som det ses paa denne Dag.',
        7: 'Og nu, Herre, min Gud! du har gjort din Tjener til Konge i min Fader Davids Sted; men jeg er et ungt Menneske, og jeg forstaar ikke at gaa ud eller ind;',
        8: 'og din Tjener er midt iblandt dit Folk, som du har udvalgt, et stort Folk, saa det ikke kan tælles eller beregnes for Mangfoldigheds Skyld:',
        9: 'Saa giv din Tjener et forstandigt Hjerte til at dømme dit Folk og til med Forstand at skelne imellem godt og ondt; thi hvo kan dømme dette dit mægtige Folk?',
        10: 'Og det Ord var godt for Herrens Øjne, at Salomo begærede denne Ting.',
        11: 'Og Gud sagde til ham: Efterdi du har begæret denne Ting og ikke har begæret dig et langt Liv og ikke har begæret dig Rigdom og ikke har begæret dine Fjenders Sjæl, men har begæret dig Forstand til at holde Dom:',
        12: 'Se, saa har jeg gjort efter dit Ord, se, jeg har givet dig et viist og forstandigt Hjerte, at der ikke har været nogen som du før dig; ej heller nogen som du skal opstaa efter dig.',
        13: 'Og jeg har endog givet dig det, som du ikke har begæret, baade Rigdom og Ære, saa at der ikke har været nogen som du iblandt Kongerne i alle dine Dage.',
        14: 'Og dersom du vandrer i mine Veje, at holde mine Skikke og mine Bud, saaledes som David din Fader har vandret, da vil jeg forlænge dine Dage.',
        15: 'Og Salomo vaagnede, og se, det var en Drøm; og han kom til Jerusalem og stod foran Herrens Pagts Ark og ofrede Brændofre og gjorde Takofre og gjorde alle sine Tjenere et Gæstebud.',
        16: 'Da kom to Kvinder, som vare Skøger, til Kongen, og de stode for hans Ansigt.',
        17: 'Og den ene Kvinde sagde: Hør mig, min Herre! jeg og denne Kvinde boede i eet Hus, og jeg fødte hos hende i Huset.',
        18: 'Og det skete paa den tredje Dag, efter at jeg havde født, da fødte ogsaa denne Kvinde; og vi vare sammen, der var ingen fremmed hos os i Huset, uden vi to i Huset.',
        19: 'Og denne Kvindes Søn døde om Natten, thi hun laa paa ham.',
        20: 'Og hun stod op midt om Natten og tog min Søn fra min Side, der din Tjenestekvinde sov, og hun lagde ham i sin Arm, og lagde sin døde Søn i min Arm.',
        21: 'Og jeg stod op om Morgenen, at give min Søn at die, se, da var han død; men om Morgenen gav jeg nøje Agt paa ham, se, da var det ikke min Søn, som jeg havde født.',
        22: 'Og den anden Kvinde sagde: Det er ikke saa; thi den levende er min Søn, men den døde er din Søn; og denne sagde: Det er ikke saa; thi den døde er din Søn, men den levende er min Søn; og de talede saa for Kongens Ansigt.',
        23: 'Da sagde Kongen: Denne siger: Denne er min Søn, den levende, og den døde er din Søn; og denne siger: Det er ikke saa; thi den døde er din Søn, men den levende er min Søn.',
        24: 'Og Kongen sagde: Henter mig et Sværd; og de bragte Sværdet ind for Kongens Ansigt.',
        25: 'Da sagde Kongen: Deler det levende Barn i to Dele, og giver den ene Halvdelen og den anden Halvdelen.',
        26: 'Da sagde Kvinden, hvis Søn den levende var, til Kongen (thi hendes inderste brændte for hendes Søn), ja hun sagde: Hør mig, min Herre! giver hende det levende Barn, og slaar det dog ikke ihjel; men hin sagde: Det skal hverken være mit eller dit, deler det.',
        27: 'Og Kongen svarede og sagde: Giver denne det levende Barn, og slaar det ikke ihjel; hun er Moder til det.',
        28: 'Og al Israel hørte Dommen, som Kongen havde dømt, og de frygtede for Kongens Ansigt; thi de saa, at Guds Visdom var i ham til at holde Dom.',
    },
    4: {
        1: 'Og Kong Salomo var Konge over al Israel.',
        2: 'Og disse vare de fornemste Befalingsmænd, som han havde: Asarja, Zadoks Søn, var Ypperstepræst;',
        3: 'Elihoref og Ahia, Sisas Sønner, vare Skrivere; Josafat, Ahiluds Søn, var Historieskriver;',
        4: 'og Benaja, Jojadas Søn, var over Hæren; og Zadok og Abjathar vare Præster;',
        5: 'og Asarja, Nathans Søn, var over Befalingsmændene; og Sabud, Nathans Søn, Præsten, var Kongens Ven;',
        6: 'og Ahisar var Hovmester; Adoniram, Abdas Søn, var Rentemester.',
        7: 'Og Salomo havde tolv Befalingsmænd over al Israel, og de forsynede Kongen og hans Hus; enhver havde en Maaned om Aaret at forsyne ham udi.',
        8: 'Og disse vare deres Navne: Hurs Søn paa Efraims Bjerg;',
        9: 'Dekers Søn i Makaz og i Saalbim og i Beth-Semes og Elon og Beth-Hanan;',
        10: 'Heseds Søn i Aruboth, han havde Soko og hele Landet Hefer;',
        11: 'Abinadabs Søn havde hele Egnen Dor, han havde Tafath, Salomos Datter, til Hustru;',
        12: 'Baena, Ahiluds Søn, havde Thaanak og Megiddo og hele Beth-Sean, som er ved Zarthan neden for Jisreel fra Beth-Sean indtil Abel-Mehola, indtil paa hin Side Jokmeam;',
        13: 'Gebers Søn var i Ramoth i Gilead; han havde Jairs, Manasse Søns, Byer, som ere i Gilead, han havde Argobs Egn, som er i Basan, tresindstyve store Stæder med Mure og med Kobberstænger;',
        14: 'Ahinadab, Iddos Søn, var i Mahanaim;',
        15: 'Ahimaaz var i Nafthali, han tog og Basmath, Salomos Datter, til Hustru;',
        16: 'Baena, Husais Søn, var i Aser og i Aloth;',
        17: 'Josafat, Faruas Søn, var i Isaskar;',
        18: 'Simei, Elas Søn, var i Benjamin;',
        19: 'Geber, Uris Søn, var i Gileads Land, i Sihons, den amoritiske Konges, og i Ogs, Kongen af Basans, Land, og det var kun een Befalingsmand, som var i dette Land.',
        20: 'Juda og Israel vare mange som Sand, der er ved Havet i Mangfoldighed; de aade og drak og vare glade.',
        21: 'Og Salomo var en Herre over alle Rigerne fra Floden til Filisternes Land og indtil Ægyptens Landemærke; de bragte ham Skænk og tjente Salomo alle hans Livsdage.',
        22: 'Og den Mad, der gik med for Salomo til hver Dag, var tredive Kor fint Mel og tresindstyve Kor Hvedemel;',
        23: 'ti fede Øksne og tyve Græsøksne og hundrede Faar, foruden Hjorte og Raadyr og Bøfler og alle Haande Fjerkræ paa Sti.',
        24: 'Thi han herskede i alt det, som laa paa denne Side af Floden, fra Thipsa og indtil Gaza, over alle Konger paa denne Side af Floden; og han havde Fred trindt omkring paa alle sine Sider.',
        25: 'Og Juda og Israel boede tryggelig, hver under sit Vintræ og under sit Figentræ, fra Dan og indtil Beersaba, alle Salomos Dage.',
        26: 'Salomo havde og fyrretyve Tusinde Stalde til sine Vognheste og tolv Tusinde Ryttere.',
        27: 'Og disse Befalingsmænd forsynede Kong Salomo og hver den, som nærmede sig til Kong Salomos Bord, hver i sin Maaned; de lode ikke fattes paa noget.',
        28: 'Og Byg og Straa til Kørehestene og til Ridehestene førte de hen til det Sted, hvor det skulde være, hver efter Anvisningen.',
        29: 'Og Gud gav Salomo Visdom og saare megen Indsigt og en omfattende Forstand, som Sand, der er ved Havets Bred.',
        30: 'Og Salomos Visdom var større end alle Østerlændernes Visdom og end alle Ægypternes Visdom.',
        31: 'Og han var visere end alle Mennesker, end Esrahiteren Ethan, og Heman og Kalkol og Darda, Mahols Sønner, og hans Navn var berømt hos alle Hedninger trindt omkring.',
        32: 'Og han fremsatte tre Tusinde Ordsprog, og hans Sange vare Tusinde og fem.',
        33: 'Og han talede om Træerne fra Cederen, som er paa Libanon, og indtil Isopen, som vokser ud af Væggen; og han talede om Dyrene og om Fuglene og om krybende Dyr og om Fiskene.',
        34: 'Og man kom fra alle Folk for at høre Salomos Visdom, fra alle Konger paa Jorden, som havde hørt om hans Visdom.',
    },
    5: {
        1: 'Og Hiram, Kongen af Tyrus, sendte sine Tjenere til Salomo, da han havde hørt, at de havde salvet ham til Konge i hans Faders Sted; thi Hiram havde elsket David alle Dage.',
        2: 'Derfor sendte Salomo til Hiram og lod sige:',
        3: 'Du ved, at min Fader David ikke kunde bygge Herrens, sin Guds, Navn et Hus for Krigens Skyld, med hvilken de havde omspændt ham, indtil Herren gav dem under hans Fødders Saaler.',
        4: 'Men nu har Herren min Gud skaffet mig Rolighed trindt omkring, her er ingen Modstander og intet ondt hændet.',
        5: 'Og se, jeg tænker at bygge Herrens, min Guds, Navn et Hus, som Herren talede til min Fader David og sagde: Din Søn, som jeg skal sætte i dit Sted paa din Trone, han skal bygge mit Navn Huset.',
        6: 'Saa befal nu, at man hugger mig Cedertræ fra Libanon, og mine Tjenere skulle være med dine Tjenere, og jeg vil give dig Løn til dine Tjenere efter alt det, som du siger; thi du ved, at her er ingen hos os, som forstaar at hugge Træer, som Zidonierne.',
        7: 'Og det skete, der Hiram hørte Salomos Ord, da blev han saare glad, og han sagde: Lovet være Herren i Dag, som har givet David en viis Søn over dette talrige Folk!',
        8: 'Og Hiram sendte hen til Salomo og lod sige: Jeg har hørt det, som du sendte til mig om; jeg vil gøre al din Villie med Cedertræer og med Fyrretræer.',
        9: 'Mine Tjenere skulle føre dem ned fra Libanon til Havet, og jeg vil lade dem lægge i Flaader paa Havet og bringe dem til det Sted, som du sender mig Bud om, og jeg vil lade dem skille ad der, og du skal lade dem hente; men du skal gøre min Villie, at give mit Hus Kost.',
        10: 'Saa gav Hiram Salomo Cedertræer og Fyrretræer, alt efter hans Villie.',
        11: 'Og Salomo gav Hiram tyve Tusinde Kor Hvede til Spise for hans Hus og tyve Kor stødt Olivenolie; saa gav Salomo Hiram fra Aar til Aar.',
        12: 'Og Herren gav Salomo Visdom, som han havde tilsagt ham; og der var Fred imellem Hiram og imellem Salomo, og de gjorde begge en Pagt.',
        13: 'Og Kong Salomo udtog Pligtarbejdere af hele Israel, og Pligtarbejderne vare tredive Tusinde Mænd.',
        14: 'Og han sendte dem til Libanon, ti Tusinde hver Maaned, saa de skiftede; en Maaned vare de paa Libanon, og to Maaneder var hver i sit Hus, og Adoniram var over Pligtarbejderne.',
        15: 'Og Salomo havde halvfjerdsindstyve Tusinde Lastdragere og firsindstyve Tusinde Tømrere paa Bjerget,',
        16: 'foruden Salomos øverste Befalingsmænd, som vare over Arbejdet, nemlig tre Tusinde og tre Hundrede, som regerede over Folket, som gjorde Arbejdet.',
        17: 'Og Kongen bød det, og de bragte store Stene, kostbare Stene, hugne Stene til at lægge Grundvolden til Huset.',
        18: 'Og Salomos Bygningsmænd og Hirams Bygningsmænd og Gibliterne tilhuggede og beredte Træerne og Stenene til at bygge Huset.',
    },
    6: {
        1: 'Og det skete i det fire Hundrede og firsindstyvende Aar, efter at Israels Børn vare udgangne af Ægyptens Land, i det fjerde Aar i Maaneden Siv, det er den anden Maaned, efter at Salomo var bleven Konge over Israel, at han byggede Herren Huset.',
        2: 'Og det Hus, som Kong Salomo byggede Herren, dets Længde var tresindstyve Alen og dets Bredde tyve, og dets Højde var tredive Alen.',
        3: 'Og Forhallen foran Templets Hus, dens Længde var tyve Alen efter Husets Bredde, ti Alen var dens Bredde foran Huset.',
        4: 'Og han gjorde paa Huset Vinduer, med snever Udsigt.',
        5: 'Og han byggede ved Husets Væg en Omgang trindt omkring, ved Væggene af Huset trindt omkring, baade om Templet og Koret, og han gjorde Sidekamre deromkring.',
        6: 'Den nederste Omgang var fem Alen vid, og den midterste var seks Alen vid, og den tredje var syv Alen vid; thi han gjorde Afsætninger uden omkring Huset, at der skulde intet hæfte ved Husets Vægge.',
        7: 'Og Huset, der det blev bygget, blev det bygget af hele Stene, som bleve tilførte, og hverken Hamre eller Økse, ej heller noget Redskab af Jern blev hørt i Huset, der det byggedes.',
        8: 'Døren til det midterste Sidekammer var paa den højre Side af Huset, og man gik igennem Vindeltrapper op paa den midterste Omgang og fra den midterste op paa den tredje.',
        9: 'Og han byggede Huset og fuldendte det, og han lagde Tag paa Huset med Bjælker og Brædder af Cedertræ.',
        10: 'Og han byggede Omgangen ved hele Huset, fem Alen var dens Højde, og den hæftede til Huset med Cederbjælker.',
        11: 'Og Herrens Ord skete til Salomo og sagde:',
        12: 'Hvad angaar dette Hus, som du bygger, dersom du vandrer i mine Skikke og gør efter mine Befalinger og holder alle mine Bud ved at vandre efter dem: Saa vil jeg paa dig stadfæste mit Ord, som jeg talede til David, din Fader.',
        13: 'Og jeg vil bo midt iblandt Israels Børn og ikke forlade mit Folk Israel.',
        14: 'Saa byggede Salomo Huset og fuldendte det.',
        15: 'Og han byggede Husets Vægge indentil af Cederplanker, fra Gulvet i Huset indtil Loftets Vægge overklædte han det indentil med Træ; han overklædte og Gulvet i Huset med Fyrreplanker.',
        16: 'Og han byggede tyve Alen til fra Husets bageste Side af med Cederplanker, fra Gulvet indtil øverst paa Væggene, og han byggede Koret der indenfor til det allerhelligste.',
        17: 'Og Huset var fyrretyve Alen langt, nemlig det hellige udenfor.',
        18: 'Og Cedertræet indentil i Huset havde udskaarne Knapper og udsprungne Blomster; det var altsammen Ceder, der saas ingen Sten.',
        19: 'Og han beredte Koret indentil i Huset, at man der skulde sætte Herrens Pagtes Ark.',
        20: 'Og Korets Længde fortil var tyve Alen, og dets Bredde tyve Alen, og dets Højde tyve Alen, og han beslog det med fint Guld og overklædte et Alter med Cedertræ.',
        21: 'Og Salomo beslog Huset indentil med fint Guld, og han drog Kæder af Guld foran Koret og beslog det med Guld.',
        22: 'Og hele Huset beslog han med Guld, indtil han var bleven færdig med hele Huset, og hele Alteret, som var for Koret, beslog han med Guld.',
        23: 'Og han gjorde i Koret to Keruber af Olietræ, ti Alen var deres Højde.',
        24: 'Og den ene Kerubs Vinge var fem Alen, og den anden Kerubs Vinge var fem Alen; der var ti Alen fra den ene Vinges Ende og til den anden Vinges Ende.',
        25: 'Og den anden Kerub var ti Alen; de to Keruber havde eet Maal og een Udskæring.',
        26: 'Den ene Kerub var ti Alen høj og ligesaa den anden Kerub.',
        27: 'Og han satte Keruberne midt i Huset indentil, og Keruberne udbredte Vingerne, og den enes Vinge rørte ved den ene Væg, og den anden Kerubs Vinge rørte ved den anden Væg; men deres Vinger midt i Huset rørte Vinge ved Vinge.',
        28: 'Og han beslog Keruberne med Guld.',
        29: 'Og paa alle Husets Vægge trindt omkring lod han sætte Snitværk af udskaarne Keruber og Palmer og udsprungne Blomster, indentil og udentil.',
        30: 'Og han belagde Gulvet i Huset med Guld, indentil og udentil.',
        31: 'Og Indgangen til Koret gjorde han med Fløjdøre af Olietræ, Dørkarmen med Dørstolperne udgjorde en Femtepart af Væggen.',
        32: 'Og paa de to Fløjdøre af Olietræ satte han Snitværk af udskaarne Keruber og Palmer og udsprungne Blomster og beslog dem med Guld, og han udbredte Guld over Keruberne og over Palmerne.',
        33: 'Saaledes gjorde han og for Indgangen til det hellige Dørstolper af Olietræ, som udgjorde den Fjerdepart af Væggen,',
        34: 'og to Dørfløje af Fyrretræ, den ene Dør havde to Fløje, som kunde opslaas, og den anden Dør havde to Fløje, som kunde opslaas.',
        35: 'Og han udskar Keruber og Palmer og udsprungne Blomster og beslog dem med Guld, som var jævnt udbredt over det, som var udgravet.',
        36: 'Og han byggede den inderste Forgaard af tre Rader udhugne Stene og en Rad tilhugne Cederstolper.',
        37: 'I det fjerde Aar blev Grundvolden lagt til Herrens Hus, i Siv Maaned.',
        38: 'Og i det ellevte Aar i Maaneden Bul, som er den ottende Maaned, blev Huset fuldkommet med alle sine Sager og med alt sit Tilbehør; og han byggede paa det i syv Aar.',
    },
    7: {
        1: 'Men Salomo byggede paa sit eget Hus tretten Aar og fuldendte hele sit Hus.',
        2: 'Og han byggede Libanons Skovhus, hundrede Alen var dets Længde og halvtredsindstyve Alen dets Bredde og tredive Alen dets Højde, paa fire Rader Cedersøjler og udhugne Cederbjælker paa Søjlerne.',
        3: 'Og det var tækket med Ceder oventil over Bjælkerne, som hvilede paa fem og fyrretyve Søjler, femten i hver Rad.',
        4: 'Og der var Stokværk i tre Rader, og Vindue over for Vindue tre Gange.',
        5: 'Og alle Døre og Dørstolper vare firkantede, af Tømmerværk, og der var Vindue over for Vindue tre Gange.',
        6: 'Og han gjorde Søjlehallen, halvtredsindstyve Alen var dens Længde og tredive Alen dens Bredde, og en Forhal foran den med Søjler og Opgangstrin foran den.',
        7: 'Han gjorde ogsaa en Tronhal, hvor han vilde dømme, en Retshal, og den var beklædt med Ceder paa Gulvet fra den ene Ende til den anden.',
        8: 'Og i hans Hus, hvori han boede, var en anden Forgaard inden for Forhallen, den var gjort efter den samme Vis; han gjorde ogsaa et Hus til Faraos Datter, som Salomo havde taget til Hustru, ligesom denne Forhal.',
        9: 'Alt dette var af kostbare Stene, hugne Stene efter Maal, savede med Save indadtil og udadtil, og det fra Grunden indtil Lejderne, ogsaa udadtil indtil den store Forgaard.',
        10: 'Grunden var ogsaa lagt af kostbare Stene, af store Stene, af Stene paa ti Alen og Stene paa otte Alen.',
        11: 'Og oventil vare kostbare Stene, hugne Stene efter Maal, og Ceder.',
        12: 'Men den store Forgaard trindt omkring var af tre Rader hugne Stene og en Rad udhugne Cederbjælker; saaledes var og Herrens Huses inderste Forgaard og Forhallen ved Huset.',
        13: 'Og Kong Salomo sendte hen og lod hente Hiram fra Tyrus.',
        14: 'Han var en Enkes Søn af Nafthalis Stamme, og hans Fader havde været en Mand fra Tyrus, en Kobbersmed; og han var opfyldt med Visdom og Forstand og Kundskab til at gøre alle Haande Gerning af Kobber, og han kom til Kong Salomo og udførte alt hans Arbejde.',
        15: 'Og han dannede to Kobberstøtter, atten Alen var Højden af den ene Støtte, og en Traad paa tolv Alen gik omkring den anden Støtte.',
        16: 'Og han gjorde to Kroner til at sætte oven paa Støtternes Hoveder, støbte af Kobber; Højden af den ene Krone var fem Alen, og Højden af den anden Krone var fem Alen.',
        17: 'Der var et Net, gjort som en Fletning, og Snore, gjorte som Kæder, om Kronerne, som vare paa Støtternes Hoveder, syv om den ene Krone og syv om den anden Krone.',
        18: 'Og han gjorde Støtterne; og der var to Rader rundt omkring ved det ene Net til at dække Kronerne, som vare oven over Granatæblerne; saaledes gjorde han og paa den anden Krone.',
        19: 'Og Kronerne, som vare paa Støtternes Hoveder, vare gjorte som en Lillie, ved Forhallen, fire Alen.',
        20: 'Og Kroner vare paa de to Støtter, ja tæt oven for Bugningen, som var oven over Nettet; og der var to Hundrede Granatæbler i to Rader rundt omkring ved den anden Krone.',
        21: 'Og han oprejste Støtterne ved Templets Forhal, og han oprejste den højre Støtte og kaldte dens Navn Jakin, og han oprejste den venstre Støtte og kaldte dens Navn Boas.',
        22: 'Og paa Støtternes Hoveder var der gjort som en Lillie; saa blev Arbejdet med Støtterne fuldendt.',
        23: 'Og han gjorde et støbt Hav; det var ti Alen fra den ene Rand til den anden Rand og var rundt trindt omkring, og fem Alen var dets Højde, og en Snor tredive Alen lang gik om det trindt omkring.',
        24: 'Og der var Knapper rundt omkring under Randen derpaa, og de gik trindt omkring det, ti paa hver Alen, og de omgave Havet trindt omkring; der var to Rader Knapper, som vare støbte i een Støbning med det selv.',
        25: 'Det stod paa tolv Okser, tre vare vendte mod Norden, og tre vare vendte mod Vesten, og tre vare vendte mod Sønden, og tre vare vendte mod Østen, og oven paa dem stod Havet, og deres Bagdele vare alle indad.',
        26: 'Og Tykkelsen derpaa var en Haandbred, og Randen derpaa var gjort som Randen paa et Bæger, ligesom et Lillieblomster; det kunde holde to Tusinde Bath.',
        27: 'Han gjorde ogsaa ti Kobberstole; Længden paa hver Stol var fire Alen og dens Bredde fire Alen og dens Højde tre Alen.',
        28: 'Og hver Stol var gjort saaledes: De havde Fyldinger, ja Fyldinger imellem Listerne.',
        29: 'Og paa Fyldingerne, som vare imellem Listerne, var der Løver, Okser og Keruber, og over Listerne var der en fast Fod oventil, og neden for Løverne og Okserne var der Løvværk af nedhængende Arbejde.',
        30: 'Og hver Stol havde fire Kobberhjul med Kobberaksler, og de fire Ben derpaa havde Skulderstykker; neden under Kedelen vare Skulderstykkerne støbte til; over for hvert var der Løvværk.',
        31: 'Og Mundingen derpaa inden for Krandsen og opad var en Alen høj, og Mundingen i denne var rund, gjort som et Fodstykke, halvanden Alen vid, og der var ogsaa om dens Munding alle Haande udskaaret Arbejde, og Fyldingerne derpaa vare firkantede, ikke runde.',
        32: 'Og de fire Hjul vare neden under Fyldingerne, og de Stykker, som grebe om Hjulakslerne, vare gjorte faste til Stolen, og hvert Hjuls Højde var halvanden Alen.',
        33: 'Og Hjulene vare gjorte, som Vognhjul gøres; de Stykker, som grebe om Akslerne, og deres Fælger og deres Eger og deres Nav vare alle støbte.',
        34: 'Og der vare fire Skulderstykker paa hver Stols fire Hjørner; ud fra Stolen gik dens Skulderstykker frem.',
        35: 'Og paa Overstykket af Stolen var der i en halv Alens Højde en Runding trindt omkring; og paa Overstykket af Stolen vare dens Haandgreb og dens Fyldinger ud af eet med den.',
        36: 'Og han lod udgrave paa Fladerne af dens Haandgreb og paa dens Fyldinger Keruber, Løver og Palmer, hvor der var bart paa enhver, og Løvværk trindt omkring.',
        37: 'Saaledes gjorde han de ti Stole, der var een Støbning, eet Maal, een Udgravning for dem alle sammen.',
        38: 'Og han gjorde ti Kobberkedler, hver Kedel kunde holde 40 Bath, hver Kedel var fire Alen, der var en Kedel paa hver Stol af de ti Stole.',
        39: 'Og han satte de fem Stole ved Siden af Huset paa den højre Side og fem ved Siden af Huset paa den venstre Side deraf; men Havet satte han paa den højre Side af Huset mod Sydøst.',
        40: 'Og Hiram gjorde Kedlerne og Ildskufferne og Skaalene, og Hiram blev færdig med alt Arbejdet, som han gjorde for Kong Salomo til Herrens Hus:',
        41: 'De to Støtter og de runde Kroner, som vare paa Hovedet af de to Støtter, og de to Net til at dække de to runde Kroner, som vare paa Hovedet af Støtterne;',
        42: 'og de fire Hundrede Granatæbler til de to Net; to Rader Granatæbler til ethvert Net for at dække de tvende runde Kroner, som vare oven paa Støtterne;',
        43: 'og de ti Stole og de ti Kedler oven paa Stolene;',
        44: 'og det ene Hav og de tolv Okser under Havet;',
        45: 'og Gryderne og Ildskufferne og Skaalene. Og alle de Kar, som Hiram gjorde for Kong Salomo til Herrens Hus, vare af poleret Kobber.',
        46: 'Paa Jordanens Slette lod Kongen dem støbe, i den faste Jord, imellem Sukot og Zarthan.',
        47: 'Og Salomo lod alle Karrene være uvejede for den saare store Mængdes Skyld; Kobberets Vægt blev ikke undersøgt.',
        48: 'Og Salomo lod gøre alle Redskaberne, som hørte til Herrens Hus, nemlig Guldalteret og Bordet, som Skuebrødene vare paa, af Guld,',
        49: 'og de fem Lysestager paa den højre Side og de fem paa den venstre Side lige for Koret, af fint Guld, og Blomsterne og Lamperne og Saksene af Guld,',
        50: 'og Bækkenerne og Knivene og Skaalene og Røgelseskaalene og Ildkarrene af fint Guld; og Hængslerne til Dørene i Huset indentil i det allerhelligste og til Husets Døre i Templet af Guld.',
        51: 'Saa blev alt Arbejdet færdigt, som Kong Salomo gjorde til Herrens Hus; og Salomo førte de Ting, som hans Fader David havde helliget, derind, nemlig Sølvet og Guldet og Karrene, og han lagde det i Herrens Huses Skatkammer.',
    },
    8: {
        1: 'Da lod Salomo de Ældste af Israel og alle Stammernes Øverster, Fædrenehusenes Fyrster iblandt Israels Børn forsamle sig til Kong Salomo i Jerusalem, for at føre Herrens Pagts Ark op fra Davids Stad, det er Zion.',
        2: 'Og alle Israels Mænd samledes til Kong Salomo i Ethanim Maaned paa Højtiden, det er den syvende Maaned.',
        3: 'Og alle de Ældste af Israel kom, og Præsterne opløftede Arken.',
        4: 'Og de førte Herrens Ark op tillige med Forsamlingens Paulun og alle Helligdommens Redskaber, som vare i Paulunet; Præsterne og Leviterne førte dem op.',
        5: 'Og Kong Salomo og al Israels Menighed, de som vare forsamlede om ham, stode hos ham foran Arken, de ofrede smaat Kvæg og stort Kvæg, som ikke kunde tælles og ikke regnes for Mangfoldigheden.',
        6: 'Og Præsterne førte Herrens Pagts Ark til dens Sted, til Koret udi Huset, ind i det allerhelligste hen under Kerubernes Vinger.',
        7: 'Thi Keruberne udbredte Vingerne imod Arkens Sted, og Keruberne dækkede over Arken og oven over dens Stænger.',
        8: 'Og man drog Stængerne langt ud, og Stængernes Knapper saas fra det hellige lige for Koret, men udenfor kunde de ikke ses, og de bleve der indtil denne Dag.',
        9: 'Der var intet i Arken uden de to Stentavler, som Mose lagde deri ved Horeb, der Herren gjorde Pagt med Israels Børn, der de vare dragne ud fra Ægyptens Land.',
        10: 'Og det skete, der Præsterne gik ud af Helligdommen, da fyldte Skyen Herrens Hus,',
        11: 'saa at Præsterne ikke kunde staa at gøre Tjeneste for Skyen; thi Herrens Herlighed fyldte Herrens Hus.',
        12: 'Da sagde Salomo: Herren sagde, at han vilde bo i Mørket.',
        13: 'Jeg har bygget dig en Boligs Hus, en fast Bolig, at du skal bo deri i al Evighed.',
        14: 'Og Kongen vendte sit Ansigt omkring og velsignede al Israels Forsamling, og al Israels Forsamling stod.',
        15: 'Og han sagde: Lovet være Herren, Israels Gud, som talede med sin Mund til David min Fader og opfyldte det med sin Haand og sagde:',
        16: 'Fra den Dag, da jeg udførte mit Folk Israel at Ægypten, har jeg ikke udvalgt en Stad af alle Israels Stammer, at man skulde bygge et Hus, for at mit Navn skulde være der; men jeg udvalgte David, at han skulde være over mit Folk Israel.',
        17: 'Og det var i min Fader Davids Hjerte, at bygge Herrens, Israels Guds, Navn et Hus.',
        18: 'Men Herren sagde til David, min Fader: Eftersom det har været i dit Hjerte at bygge mit Navn et Hus, saa gjorde du vel deri, at det var i dit Hjerte.',
        19: 'Dog skal du ikke bygge det Hus, men din Søn, han som udgaar af dine Lænder, han skal bygge mit Navn et Hus.',
        20: 'Og Herren har opfyldt sit Ord, som han talede; thi jeg er kommen op i Davids, min Faders, Sted og sidder paa Israels Trone, saaledes som Herren talede, og har bygget Herrens, Israels Guds, Navn et Hus.',
        21: 'Og jeg har beskikket der et Sted til Arken, hvori Herrens Pagt er, som han gjorde med vore Fædre, der han førte dem ud af Ægyptens Land.',
        22: 'Og Salomo stod foran Herrens Alter for al Israels Forsamling og udbredte sine Hænder imod Himmelen,',
        23: 'og han sagde: Herre, Israels Gud! der er ingen Gud som du i Himmelen oventil eller paa Jorden nedentil, du som holder Pagten og Miskundheden med dine Tjenere, som vandre for dit Ansigt af deres ganske Hjerte;',
        24: 'du, som har holdt din Tjener David, min Fader, det, som du har tilsagt ham; du har talt det med din Mund og opfyldt det med din Haand, som det ses paa denne Dag;',
        25: 'og nu, Herre Israels Gud! hold din Tjener David, min Fader, det, du har tilsagt ham og sagt: Dig skal ikke fattes en Mand for mit Ansigt, som skal sidde paa Israels Trone, naar ikkun dine Børn bevare deres Vej, at vandre for mit Ansigt, saaledes som du har vandret for mit Ansigt.',
        26: 'Og nu, Israels Gud! lad dog dit Ord staa fast, som du talede til din Tjener David, min Fader.',
        27: 'Thi sandelig, monne Gud skulde bo paa Jorden? Se, Himlene og Himlenes Himle kunne ikke rumme dig, langt mindre dette Hus, som jeg har bygget.',
        28: 'Men vend dit Ansigt til din Tjeners Bøn og til hans ydmyge Begæring, Herre, min Gud! at høre paa det Raab og paa den Bøn, som din Tjener beder for dit Ansigt i Dag:',
        29: 'At dine Øjne maa være aabnede over dette Hus Nat og Dag, over dette Sted, om hvilket du har sagt: Mit Navn skal være der, til at høre den Bøn, som din Tjener beder paa dette Sted;',
        30: 'og at du vil høre din Tjeners og dit Folk Israels ydmyge Begæring, som de skulle bede paa dette Sted, og at du vil høre paa det Sted, hvor du bor i Himmelen, og vil høre og forlade.',
        31: 'Naar nogen synder imod sin Næste, og man paalægger ham en Ed, som han skal sværge, og den Ed kommer for dit Alter i dette Hus:',
        32: 'Da vil du høre i Himmelen og gøre derefter og dømme dine Tjenere, saa at du fordømmer den ugudelige og fører hans Vej over hans Hoved og retfærdiggør den retfærdige og giver ham efter hans Retfærdighed.',
        33: 'Naar dit Folk Israel bliver slaget for Fjendens Ansigt, fordi de have syndet imod dig, og de da omvende sig til dig og bekende dit Navn og bede og bønfalde dig om Naade i dette Hus:',
        34: 'Da vil du høre i Himmelen og forlade dit Folk Israels Synd og føre dem tilbage i det Land, som du har givet deres Fædre.',
        35: 'Naar Himmelen bliver tillukt, og der vorder ikke Regn, fordi de have syndet imod dig, og de bede paa dette Sted og bekende dit Navn og omvende sig fra deres Synder, fordi du ydmyger dem:',
        36: 'Da vil du høre i Himmelen og forlade dine Tjeneres og dit Folk Israels Synd, fordi du viser dem den gode Vej, paa hvilken de skulle vandre, og vil give Regn over dit Land, som du har givet dit Folk til Arv.',
        37: 'Naar der vorder Hunger i Landet, naar der vorder Pest, naar der vorder Tørke, Brand i Korn, Græshopper, Kornorme, naar hans Fjende ængster ham i hans Stæders Land, naar der kommer alle Haande Plage, alle Haande Sygdom:',
        38: 'Al Bøn, al ydmyg Begæring, som sker af hvert Menneske eller af alt dit Folk Israel, som kender hver sit Hjertes Plage og udbreder sine Hænder til dette Hus,',
        39: 'den vil du da høre i Himmelen, i den faste Bolig, i hvilken du bor, og forlade og gøre derefter og give enhver efter alle hans Veje, ligesom du kender hans Hjerte; thi du alene kender alle Menneskenes Børns Hjerter;',
        40: 'paa det de skulle frygte dig alle de Dage, hvilke de leve i Landet, som du har givet vore Fædre.',
        41: 'Ja ogsaa den fremmede, som ikke er af dit Folk Israel, naar han kommer fra et langtfra liggende Land for dit Navns Skyld;',
        42: '(thi de skulle høre om dit store Navn og om din stærke Haand og din udrakte Arm) og nogen kommer og beder mod dette Hus:',
        43: 'Ham vil du da høre i Himmelen, i den faste Bolig, i hvilken du bor, og gøre efter alt det, som den fremmede raaber til dig om, paa det at alle Folk paa Jorden kunne kende dit Navn og frygte dig, ligesom dit Folk Israel, og at de skulle vide, at dette Hus, som jeg har bygget, er kaldet efter dit Navn.',
        44: 'Naar dit Folk drager ud i Krigen imod sin Fjende paa den Vej, hvor du sender dem hen, og de bede til Herren, vendte mod den Stad, som du udvalgte, og imod det Hus, som jeg har bygget til dit Navn:',
        45: 'Da vil du høre i Himmelen deres Bøn og deres ydmyge Begæring og skaffe dem Ret.',
        46: 'Naar de synde imod dig, (thi der er intet Menneske, som jo synder) og du bliver vred paa dem og giver dem hen for Fjendens Ansigt, og de, som have fanget dem, føre dem fangne til Fjendens Land, langt borte eller nær hos;',
        47: 'og de tage det igen til Hjerte i Landet, hvori de ere fangne, og omvende sig og bede til dig om Naade i deres Land, som have taget dem fangne, og sige: Vi have syndet og handlet ilde, vi have været ugudelige;',
        48: 'og de omvende sig til dig af deres ganske Hjerte og af deres ganske Sjæl i deres Fjenders Land, som have taget dem fangne, og de bede til dig, vendte imod deres Land, som du har givet til deres Fædre, imod Staden, som du udvalgte, og Huset, som jeg har bygget for dit Navn:',
        49: 'Da vil du høre i Himmelen, i din faste Bolig, i hvilken du bor, deres Bøn og deres ydmyge Begæringer og skaffe dem Ret',
        50: 'og forlade dit Folk det, som de have syndet imod dig, og alle deres Overtrædelser, som de have begaaet imod dig, og lade dem finde Barmhjertighed for deres Ansigt, som holde dem fangne, at disse maa forbarme sig over dem;',
        51: 'thi de ere dit Folk og din Arv, som du udførte af Ægypten, midt ud af Jernovnen;',
        52: 'at dine Øjne maa være aabnede til din Tjeners ydmyge Begæring og til dit Folk Israels ydmyge Begæring, at du vil høre dem i alt det, hvori de paakalde dig.',
        53: 'Thi du udskilte dig dem af alle Folk paa Jorden til en Arv, saaledes som du talede ved Mose, din Tjener, da du udførte vore Fædre af Ægypten, Herre, Herre!',
        54: 'Og det skete, der Salomo havde fuldendt at bede til Herren hele denne Bøn og ydmyge Begæring, da stod han op fra Herrens Alter, fra at knæle paa sine Knæ, med sine Hænder udbredte imod Himmelen,',
        55: 'og han stod og velsignede hele Israels Forsamling med høj Røst og sagde:',
        56: 'Lovet være Herren, som har givet sit Folk Israel Rolighed efter alt det, som han har talt! der blev ikke et Ord til intet af alle hans gode Ord, som han talede ved Mose, sin Tjener.',
        57: 'Herren vor Gud være med os, ligesom han har været med vore Fædre! Han forlade os ikke og overgive os ikke!',
        58: 'at han vil bøje vort Hjerte til sig, saa at vi vandre i alle hans Veje og holde hans Bud og hans Skikke og hans Befalinger, som han har budet vore Fædre,',
        59: 'og at disse mine Ord, som jeg har bedet ydmygeligt med for Herrens Ansigt, maa komme nær for Herren vor Gud Dag og Nat, at han vil skaffe sin Tjener Ret og sit Folk, Israel, Ret, hver Dags Sag paa sin Dag,',
        60: 'paa det at alle Folk paa Jorden skulle vide, at Herren han er Gud, og ingen ydermere,',
        61: 'og at eders Hjerter maa være retskafne for Herren vor Gud til at vandre i hans Skikke og til at holde hans Bud som paa denne Dag.',
        62: 'Og Kongen og al Israel med ham ofrede Offer for Herrens Ansigt.',
        63: 'Og Salomo ofrede Takofre, som han ofrede til Herren, to og tyve Tusinde Øksne og Hundrede og tyve Tusinde Faar; saa indviede Kongen og alle Israels Børn Herrens Hus.',
        64: 'Paa den samme Dag helligede Kongen den mellemste Part af Forgaarden, som var lige for Herrens Hus; thi han lavede der Brændofret og Madofret og Takofrenes Fedtstykker, fordi det Kobberalter, som stod for Herrens Ansigt, var for lidet til at tage imod Brændofret og Madofret og Takofrenes Fedtstykker.',
        65: 'Og Salomo holdt paa den samme Tid Højtiden og al Israel med ham, en stor Forsamling fra Strækningen mellem Hamath og Ægyptens Bæk, for Herrens vor Guds Ansigt i syv Dage og atter i syv Dage, det var fjorten Dage.',
        66: 'Paa den ottende Dag lod han Folket fare, og de velsignede Kongen, og de gik glade til deres Telte og vel til Mode i Hjertet over alt det gode, som Herren havde gjort David, sin Tjener, og Israel, sit Folk.',
    },
    9: {
        1: 'Og det skete, der Salomo havde fuldendt at bygge Herrens Hus og Kongens Hus og alt, som Salomo begærede, som han havde Lyst til at gøre:',
        2: 'Da aabenbarede Herren sig for Salomo anden Gang, ligesom han havde aabenbaret sig for ham i Gibeon.',
        3: 'Og Herren sagde til ham: Jeg har hørt din Bøn og din ydmyge Begæring, som du ydmygeligt har bedet med for mit Ansigt, jeg har helliget dette Hus, som du har bygget, at jeg vil sætte mit Navn der indtil evig Tid, og mine Øjne og mit Hjerte skulle være der alle Dage.',
        4: 'Og du, dersom du vandrer for mit Ansigt, ligesom David, din Fader, vandrede, med et fuldkomment Hjerte og med Oprigtighed til at gøre efter alt det, som jeg har budet dig, og du holder mine Skikke og mine Forskrifter:',
        5: 'Da vil jeg stadfæste dit Riges Trone over Israel evindeligt, ligesom jeg talte til David, din Fader, og sagde: Dig skal ikke fattes en Mand paa Israels Trone.',
        6: 'Dersom I vende eder bort, I og eders Børn, fra mig og ikke holde mine Bud og mine Skikke, som jeg gav for eders Ansigt, og I gaa hen og tjene andre Guder og tilbede dem:',
        7: 'Da vil jeg udrydde Israel fra at være i Landet, som jeg har givet dem, og det Hus, som jeg har helliget til mit Navn, vil jeg forkaste fra mit Ansigt, og Israel skal blive til et Ordsprog og til en Spot iblandt alle Folk.',
        8: 'Og saa højt end dette Hus monne være, skulle dog alle, som gaa forbi det, grue og hvisle, og de skulle sige: Hvorfor har Herren gjort saaledes ved dette Land og ved dette Hus?',
        9: 'Og de skulle sige: Fordi de forlode Herren deres Gud, som udførte deres Fædre af Ægyptens Land, og holdt fast ved andre Guder og tilbade dem og tjente dem, derfor har Herren ladet alt dette onde komme over dem.',
        10: 'Og det skete, der de tyve Aar vare til Ende, i hvilke Salomo byggede de to Huse, Herrens Hus og Kongens Hus,',
        11: 'og Hiram, Kongen i Tyrus, havde hjulpet Salomo med Cedertræer og Fyrretræer og med Guldet efter al hans Lyst: Da gav Kong Salomo Hiram tyve Stæder i Galilæas Land.',
        12: 'Og Hiram drog ud af Tyrus for at bese de Stæder, som Salomo havde givet ham, og de behagede ham ikke.',
        13: 'Og han sagde: Hvad er dette for Stæder, min Broder, som du har givet mig? og han kaldte dem Kabul-Land indtil denne Dag.',
        14: 'Og Hiram havde sendt til Kongen Hundrede og tyve Centner Guld.',
        15: 'Saaledes forholdt det sig med de Pligtarbejdere, som Kong Salomo udtog til at bygge Herrens Hus og sit Hus og Millo og Jerusalems Mur og Hazor og Megiddo og Geser: —',
        16: 'Farao, Kongen af Ægypten, var dragen op og havde indtaget Geser og opbrændt den med Ild og ihjelslaget Kananiten, som boede i Staden, og givet sin Datter, Salomos Hustru, den til Medgift.',
        17: 'Saa byggede Salomo Geser og det nedre Beth-Horon',
        18: 'og Baalath og Thadmor i Ørken udi Landet',
        19: 'og alle de Forraadsstæder, som Salomo havde, og Vognstæder og Stæder til Ryttere og det, som Salomo begærede, som han havde Lyst til at bygge i Jerusalem og paa Libanon og i hele sit Herredømmes Land: —',
        20: 'Alt det Folk, som var overblevet af Amoriter, Hethiter, Feresiter, Heviter og Jebusiter, de, som ikke vare af Israels Børn,',
        21: 'deres Børn, som vare overblevne efter dem i Landet, og som Israels Børn ikke havde kunnet ødelægge, dem udtog Salomo til at være arbejdspligtige Tjenere indtil denne Dag.',
        22: 'Men Salomo gjorde ikke nogen af Israels Børn til Træl; men de vare Krigsmænd og hans Tjenere og hans Fyrster og hans Høvedsmænd og Øverster over hans Vogne og hans Ryttere.',
        23: 'Disse vare de øverste Befalingsmænd, som vare over Salomos Arbejder, fem Hundrede og halvtredsindstyve, de som regerede over det Folk, som gjorde Arbejdet.',
        24: 'Der Faraos Datter drog op fra Davids Stad ind i sit Hus, som han havde bygget til hende, da byggede han Millo.',
        25: 'Og Salomo ofrede tre Gange om Aaret Brændofre og Takofre paa det Alter, som han byggede Herren, og gjorde Røgelse paa det, som var for Herrens Ansigt, og han havde fuldendt Huset.',
        26: 'Og Kong Salomo lod gøre Skibe i Eziongeber, som er ved Eloth, ved det røde Havs Bred, i Edoms Land',
        27: 'Og Hiram sendte sine Tjenere paa de Skibe, Skibsmænd, forfarne til Søs, med Salomos Tjenere.',
        28: 'Og de kom til Ofir og hentede derfra fire Hundrede og tyve Centner Guld og førte det til Kong Salomo.',
    },
    10: {
        1: 'Og Dronningen af Seba hørte Salomos Rygte i Herrens Navn og kom for at prøve ham med mørke Taler.',
        2: 'Og hun kom til Jerusalem med en saare stor Skare, med Kameler, som bare vellugtende Urter og saare meget Guld og kostbare Stene; og hun kom til Salomo og talte med ham alt det, som var i hendes Hjerte.',
        3: 'Og Salomo udtydede hende alle hendes Ord; der var ikke et Ord skjult for Kongen, som han ej udtydede hende.',
        4: 'Da Dronningen af Seba saa al Salomos Visdom og Huset, som han havde bygget,',
        5: 'og Maden til hans Bord og hans Tjeneres Bolig, og hvordan de stode, som opvartede ham, og deres Klæder og hans Mundskænke og hans Opgang, ad hvilken han gik op til Herrens Hus: Da var hun ude af sig selv.',
        6: 'Og hun sagde til Kongen: Det Ord er sandt, som jeg har hørt i mit Land om dine Sager og om din Visdom.',
        7: 'Og jeg troede ikke Ordene, førend jeg kom, og mine Øjne saa det, og se, ikke Halvdelen er mig forkyndt; du har mere Visdom og godt end efter Rygtet, sofh jeg hørte.',
        8: 'Salige ere dine Mænd, salige ere disse dine Tjenere, som stedse staa for dit Ansigt, og som høre din Visdom.',
        9: 'Lovet være Herren din Gud, som havde Lyst til at sætte dig paa Israels Trone; fordi Herren elsker Israel evindeligt, derfor satte han dig til Konge at gøre Ret og Retfærdighed.',
        10: 'Og hun gav Kongen Hundrede og tyve Centner Guld og saare mange vellugtende Urter og kostbare Stene, der kom ikke ydermere saadanne Urter i Mangfoldighed som disse, hvilke Dronningen af Seba gav Kong Salomo.',
        11: 'Dertilmed havde Hirams Skibe, som bragte Guld fra Ofir, ført saare meget Hebentræ og kostbare Stene fra Ofir.',
        12: 'Og Kongen lod gøre Piller i Herrens Hus og i Kongens Hus af Hebentræ og Harper og Salter til Sangerne; saadant Hebentræ kom ikke og blev ikke ydermere set indtil denne Dag.',
        13: 'Og Kong Salomo gav Dronningen af Seba alt det, hun havde Lyst til, som hun begærede, foruden det, han gav hende efter Kong Salomos Formue; og hun vendte om og drog til sit Land, hun og hendes Tjenere.',
        14: 'Og Vægten paa det Guld, som kom til Salomo paa et Aar, var seks Hundrede seks og tresindstyve Centner Guld,',
        15: 'foruden det, som indkom fra Toldbetjentene og Kræmmernes Købmandskab og fra alle Kongerne i Arabien og Fyrsterne i Landet.',
        16: 'Og Kong Salomo lod gøre to Hundrede Skjolde af drevet Guld; seks Hundrede Sekel Guld lod han gaa paa hvert Skjold;',
        17: 'og tre Hundrede smaa Skjolde af drevet Guld; tre Pund Guld lod han gaa paa hvert Skjold; og Kongen lagde dem i Libanons Skovhus.',
        18: 'Og Kongen lod gøre en stor Trone af Elfenben og beslog den med lutret Guld.',
        19: 'Tronen havde seks Trin, og Hovedet paa Tronen var rundt bagtil, og der var Arme paa begge Sider til Sædets Sted, og to Løver stode ved Armene.',
        20: 'Og der stod tolv Løver paa de seks Trin paa begge Sider; saadant er ikke gjort i noget Rige.',
        21: 'Og alle Kong Salomos Drikkekar vare af Guld, og alle Kar i Libanons Skovhus vare af fint Guld; der var intet Kar af Sølv, det agtedes ikke for noget i Salomos Dage;',
        22: 'fordi Kongen havde Tharsisskibe paa Havet med Hirams Skibe, een Gang i tre Aar kom Tharsisskibene, som bragte Guld og Sølv, Elfenben og Aber og Paafugle.',
        23: 'Og Kong Salomo blev større end alle Konger paa Jorden ved Rigdom og ved Visdom.',
        24: 'Og fra alle Lande søgte de Salomo for at høre hans Visdom, som Gud havde givet i hans Hjerte.',
        25: 'Og de førte hver sin Skænk, Sølvkar og Guldkar og Klæder og Rustning og vellugtende Urter, Heste og Muler, hvilket skete aarligt.',
        26: 'Og Salomo samlede Vogne og Ryttere, saa at han havde Tusinde og fire Hundrede Vogne og tolv Tusinde Ryttere, og han lod dem blive i Vognstæderne og hos Kongen i Jerusalem.',
        27: 'Og Kongen gjorde Sølvet i Jerusalem som Stenene og gjorde Cedertræerne som Morbærtræerne, der ere i Lavlandet, i Mangfoldighed.',
        28: 'Og Udførselen af Heste skete for Salomo fra Ægypten; og en Skare af Kongens Købmænd hentede en Skare for rede Penge.',
        29: 'Og der kom op og udførtes en Vogn af Ægypten for seks Hundrede Sekel Sølv og en Hest for Hundrede og halvtredsindstyve; og saaledes førte de dem ud til alle Hethiternes Konger og til Kongerne i Syrien ved egen Haand.',
    },
    11: {
        1: 'Og Kong Salomo elskede mange fremmede Kvinder foruden Faraos Datter, moabitiske, ammonitiske, edomitiske, zidonitiske, hethitiske,',
        2: 'af de Hedninger, om hvilke Herren havde sagt til Israels Børn: Gaar ikke ind til dem og lader dem ikke komme ind til eder, de skulle visselig bøje eders Hjerter efter deres Guder; ved disse hængte Salomo med Kærlighed.',
        3: 'Og hans Hustruer vare syv Hundrede Fruer og tre Hundrede Medhustruer; og hans Hustruer bøjede hans Hjerte.',
        4: 'Og det skete, den Tid Salomo blev gammel, bøjede hans Hustruer hans Hjerte efter andre Guder; og hans Hjerte var ikke helt med Herren hans Gud som Davids, hans Faders, Hjerte.',
        5: 'Thi Salomo vandrede efter Astoreth, Zidoniernes Gud, og efter Milkom, Ammoniternes Vederstyggelighed.',
        6: 'Og Salomo gjorde det, som var ondt for Herrens Øjne, og vandrede ikke fuldkommelig efter Herren som David, hans Fader.',
        7: 'Da byggede Salomo en Høj til Kamos, Moabs Vederstyggelighed, paa Bjerget, som ligger lige for Jerusalem, og til Molek, Ammons Børns Vederstyggelighed.',
        8: 'Og saa gjorde han for alle sine fremmede Kvinder, som gave Røgelse og ofrede til deres Guder.',
        9: 'Og Herren blev vred paa Salomo, fordi hans Hjerte bøjede sig fra Herren, Israels Gud, som havde aabenbaret sig for ham to Gange,',
        10: 'og som havde givet ham Befaling om denne Sag, at han ikke skulde vandre efter andre Guder, og han holdt ikke det, som Herren havde befalet.',
        11: 'Derfor sagde Herren til Salomo: Efterdi saadant er hos dig, og du ikke har holdt min Pagt og mine Skikke, som jeg har budet dig, vil jeg visselig rive Riget fra dig og give din Tjener det.',
        12: 'Dog vil jeg ikke gøre det i dine Dage, for Davids, din Faders, Skyld; af din Søns Haand vil jeg rive det.',
        13: 'Dog vil jeg ikke rive det ganske Rige fra dig; een Stamme vil jeg give din Søn, for Davids, min Tjeners Skyld, og for Jerusalems Skyld, som jeg har udvalgt.',
        14: 'Og Herren opvakte Salomo en Modstander, nemlig Edomiteren Hadad, han var af Kongens Sæd i Edom.',
        15: 'Thi det skete, der David var i Edom, der Joab, Stridshøvedsmanden, drog op at begrave de ihjelslagne, da slog han alt Mandkøn i Edom.',
        16: 'Thi Joab og al Israel bleve der seks Maaneder, indtil han havde udryddet alt Mandkøn i Edom.',
        17: 'Men Hadad flyede, han og nogle edomitiske Mænd af hans Faders Tjenere med ham, for at komme til Ægypten, og Hadad var en liden Dreng.',
        18: 'Og de droge op fra Midian og kom til Paran, og de toge Mænd med sig fra Paran og kom til Ægypten til Farao, Kongen i Ægypten, og han gav ham et Hus og tilsagde ham Underholdning og gav ham Land.',
        19: "Og Hadad fandt stor Naade for Faraos Øjne; og han gav ham til Hustru sin Hustrus Søster, Dronning Takfenes's Søster.",
        20: "Og Takfenes's Søster fødte ham Genubath, hans Søn, og Takfenes afvante ham udi Faraos Hus, og Genubath var i Faraos Hus midt iblandt Faraos Børn.",
        21: 'Der Hadad hørte i Ægypten, at David laa med sine Fædre, og at Joab, Stridshøvedsmanden, var død, da sagde Hadad til Farao: Lad mig fare, at jeg kan drage til mit Land.',
        22: 'Og Farao sagde til ham: Men hvad fattes dig hos mig? og se, du søger at drage til dit Land; og han sagde: Mig fattes intet, men lad mig dog fare.',
        23: 'Gud opvakte ham ogsaa en Modstander, Reson, Eljadas Søn, som flyede fra sin Herre Hadad-Eser, Kongen af Zoba,',
        24: 'og samlede Mænd til sig og blev Høvedsmand for en Trop, der David slog dem; og de droge til Damaskus og boede i den og regerede i Damaskus.',
        25: 'Og han var Israels Modstander alle Salomos Dage, og det var foruden det onde, som Hadad gjorde; og han hadede Israel og blev Konge over Syrien.',
        26: 'Og Jeroboam, Nebats Søn, en Efratiter fra Zareda, hvis Moders Navn var Zerua, en Enke, Salomos Tjener, han opløftede ogsaa Haand imod Kongen.',
        27: 'Og dette er Sagen, hvorfor han opløftede Haand imod Kongen: Salomo byggede Millo og tillukkede det aabne Sted paa Davids sin Faders Stad.',
        28: "Og Manden Jeroboam var et dygtigt Menneske, og der Salomo saa den unge Karl, at han udrettede Gerningen vel, da beskikkede han ham over alt Josefs Hus's Arbejde.",
        29: 'Og det skete paa samme Tid, da Jeroboam gik ud af Jerusalem, at Siloniteren Ahia, Profeten, traf ham paa Vejen og han var iført et nyt Klædebon, og de to vare alene paa Marken.',
        30: 'Og Ahia tog fat i det nye Klædebon, som han havde paa sig, og han rev det i tolv Stykker.',
        31: 'Og han sagde til Jeroboam: Tag ti Stykker til dig; thi saa siger Herren, Israels Gud: Se, jeg river Riget af Salomos Haand og vil give dig de ti Stammer.',
        32: 'Men han skal have den ene Stamme for min Tjener Davids Skyld og for Jerusalems Stads Skyld, som jeg udvalgte af alle Israels Stammer;',
        33: 'fordi de have forladt mig og nedbøjet sig for Astoreth, Zidoniernes Gud, for Kamos, Moabiternes Gud, og for Milkom, Ammons Børns Gud, og de have ikke vandret i mine Veje til at gøre, hvad ret var for mine Øjne, og mine Skikke og mine Forskrifter som David hans Fader.',
        34: 'Dog vil jeg ikke tage noget af Riget ud af hans Haand; men jeg vil lade ham blive en Fyrste i alle hans Livs Dage, for Davids min Tjeners Skyld, som jeg udvalgte, som holdt mine Bud og mine Skikke.',
        35: 'Men jeg vil tage Riget ud af hans Søns Haand og give dig de ti Stammer.',
        36: 'Og jeg vil give hans Søn en Stamme, paa det David, min Tjener, skal alle Dage have et Lys for mit Ansigt i Jerusalem, den Stad, som jeg udvalgte mig, at sætte mit Navn der.',
        37: 'Og dig vil jeg antage, at du skal regere over alt det, din Sjæl begærer, og du skal være Konge over Israel.',
        38: 'Og det skal ske, dersom du hører alt det, jeg byder dig, og vandrer i mine Veje og gør det, som er ret for mine Øjne, at holde mine Skikke og mine Bud, saaledes som David, min Tjener, gjorde: Da vil jeg være med dig og bygge et bestandigt Hus, saaledes som jeg byggede David, og give dig Israel.',
        39: 'Og jeg vil ydmyge Davids Sæd for denne Sags Skyld, dog ikke alle Dage.',
        40: 'Og Salomo søgte efter at dræbe Jeroboam; da gjorde Jeroboam sig rede og flyede til Ægypten, til Sisak, Kongen i Ægypten, og blev i Ægypten, indtil Salomo døde.',
        41: 'Men det øvrige af Salomos Handeler, og alt, hvad han har gjort, og hans Visdom, ere de Ting ikke skrevne i Salomos Krønikers Bog?',
        42: 'Men Dagene, som Salomo var Konge i Jerusalem over al Israel, vare fyrretyve Aar.',
        43: 'Og Salomo laa med sine Fædre og blev begraven i Davids, sin Faders, Stad; og Roboam, hans Søn, blev Konge i hans Sted.',
    },
    12: {
        1: 'Og Roboam drog til Sikem; thi al Israel var kommen til Sikem for at gøre ham til Konge.',
        2: 'Og det skete, der Jeroboam, Nebats Søn, hørte det — han var endnu i Ægypten, hvorhen han var flygtet fra Kong Salomos Ansigt, og Jeroboam boede i Ægypten,',
        3: 'og de sendte hen og kaldte ham — saa kom Jeroboam og al Israels Menighed, og de talte med Roboam og sagde:',
        4: 'Din Fader gjorde vort Aag haardt; men gør du os nu din Faders haarde Tjeneste og hans svare Aag, som han lagde paa os, lettere, saa ville vi tjene dig.',
        5: 'Og han sagde til dem: Gaar hen endnu i tre Dage, og kommer igen til mig; og Folket gik.',
        6: 'Og Kong Roboam raadførte sig med de ældste, som havde staaet for hans Fader Salomos Ansigt, der han var levende, og sagde: Hvorledes raade I at give dette Folk Svar tilbage?',
        7: 'Og de sagde til ham saaledes: Dersom du vil være dette Folk til Tjeneste i Dag, og tjene dem og svare dem vel og tale gode Ord til dem, da blive de dine Tjenere alle Dage.',
        8: 'Men han forlod de ældstes Raad, som de madede ham, og raadførte sig med de unge, som vare opvoksede med ham, dem som stode for hans Ansigt.',
        9: 'Og han sagde til dem: Hvad raade I, at vi skulle give dette Folk for Svar tilbage, som talte til mig, sigende: Gør du os dette Aag lettere, som din Fader lagde paa os?',
        10: 'Og de unge, som vare opvoksede med ham, talte til ham, sigende: Saa skal du sige til det Folk, som talte til dig og sagde: Din Fader gjorde vort Aag svart, men gør du os det lettere, saa skal du tale til dem: Min Lillefinger skal være tykkere end min Faders Lænder.',
        11: 'Nu da, min Fader lagde eder et svart Aag paa, men jeg, jeg vil gøre eders Aag svarere; min Fader tugtede eder med Svøber, men jeg, jeg vil tugte eder med Skorpioner.',
        12: 'Saa kom Jeroboam og alt Folket til Roboam paa den tredje Dag, som Kongen havde talt og sagt: Kommer igen til mig paa den tredje Dag!',
        13: 'Og Kongen svarede Folket haardt og forlod de ældstes Raad, som de havde raadet ham.',
        14: 'Og han talte til dem efter de unges Raad og sagde: Min Fader gjorde eders Aag svart, men jeg, jeg vil gøre eders Aag svarere; min Fader tugtede eder med Svøber, men jeg, jeg vil tugte eder med Skorpioner.',
        15: 'Og Kongen hørte ikke Folket; thi Aarsagen var fra Herren, for at han kunde stadfæste sit Ord, som Herren havde talt ved Siloniteren Ahia til Jeroboam, Nebats Søn.',
        16: 'Der al Israel saa, at Kongen ikke vilde høre dem, da gav Folket Kongen et Svar tilbage og sagde: Hvad Del have vi da i David? vi have ingen Lod i Isajs Søn; Israel! drag til dine Telte; se nu til dit Hus, o David! Saa gik Israel til sine Telte.',
        17: 'Dog Israels Børn, som boede i Judas Stæder, over dem regerede Roboam.',
        18: 'Da sendte Kong Roboam Adoram, som var Rentemester, til dem, og al Israel stenede ham med Stene, saa at han døde; men Kong Roboam brugte al sin Styrke til at komme op i Vognen for at fly til Jerusalem.',
        19: 'Saa faldt Israel af fra Davids Hus indtil denne Dag.',
        20: 'Og det skete, der al Israel hørte, at Jeroboam var kommen tilbage, da sendte de hen og kaldte ham til Menigheden og gjorde ham til Konge over al Israel; der var ingen, som fulgte efter Davids Hus, undtagen Judas Stamme alene.',
        21: 'Der Roboam kom til Jerusalem, da samlede han alt Judas Hus og Benjamins Stamme, hundrede og firsindstyve Tusinde udvalgte Krigsmænd, for at stride imod Israels Hus, at føre Riget tilbage til Roboam, Salomos Søn.',
        22: 'Men Guds Ord skete til Semaja, den Guds Mand, og sagde:',
        23: 'Tal til Roboam, Salomos Søn, Judas Konge, og til al Judas Hus og Benjamin og til det øvrige Folk, og sig:',
        24: 'Saaledes sagde Herren: I skulle ikke drage op og ej stride imod eders Brødre, Israels Børn, vender tilbage hver til sit Hus, thi denne Handel er sket af mig; og de adløde Herrens Ord og vendte tilbage for at gaa bort efter Herrens Ord.',
        25: 'Og Jeroboam byggede Sikem paa Efraims Bjerg og boede derudi, og han drog ud derfra og byggede Pnuel.',
        26: 'Og Jeroboam tænkte i sit Hjerte: Nu maatte Riget vende tilbage til Davids Hus.',
        27: 'Dersom dette Folk skal gaa op at gøre Offer i Herrens Hus i Jerusalem, saa maatte dette Folks Hjerte vende tilbage til deres Herre, til Roboam, Judas Konge, ja de maatte slaa mig ihjel og vende tilbage til Roboam, Judas Konge.',
        28: 'Derfor holdt Kongen et Raad og gjorde to Guldkalve; og han sagde til dem: Det er eder for meget at gaa op til Jerusalem; se dine Guder, Israel! som førte dig op af Ægyptens Land.',
        29: 'Og han satte den ene i Bethel, og den anden satte han i Dan.',
        30: 'Og denne Gerning blev til Synd; og Folket lige til Dan gik hen til en af dem.',
        31: 'Han gjorde Huset paa Højene og gjorde Præster af Folket i Flæng, som ikke vare af Levi Børn.',
        32: 'Og Jeroboam gjorde en Højtid i den ottende Maaned paa den femtende Dag i Maaneden ligesom Højtiden, som var i Juda, og ofrede paa Alteret; saaledes gjorde han i Bethel for at ofre til Kalvene, som han havde gjort; og han beskikkede Præster i Bethel til Højene, som han havde gjort.',
        33: 'Og han ofrede paa Alteret, som han havde gjort i Bethel, paa den femtende Dag i den ottende Maaned, i Maaneden, som han havde optænkt af sit eget Hjerte, og gjorde en Højtid for Israels Børn og ofrede paa Alteret til at gøre Røgelse.',
    },
    13: {
        1: 'Og se, der kom en Guds Mand af Juda efter Herrens Ord til Bethel, medens Jeroboam stod ved Alteret for at gøre Røgelse.',
        2: 'Og han raabte imod Alteret efter Herrens Ord og sagde: Alter! Alter! saa sagde Herren: Se, for Davids Hus skal fødes en Søn, hvis Navn skal være Josias, og han skal ofre paa dig Højenes Præster, som gøre Røgelse paa dig, og de skulle opbrænde Menneskers Ben paa dig.',
        3: 'Og han gav paa den samme Dag et underligt Tegn og sagde: Dette er det underlige Tegn paa, at Herren har talt dette: Se, Alteret skal revne, og Asken, som er derpaa, skal adspredes.',
        4: 'Og det skete, der Kongen hørte den Guds Mands Ord, som raabte imod Alteret i Bethel, da rakte Jeroboam sin Haand ud fra Alteret og sagde: Griber ham! og hans Haand visnede, som han udrakte imod ham, saa at han ikke kunde drage den tilbage til sig.',
        5: 'Og Alteret revnede, og Asken blev adspredt fra Alteret efter det underlige Tegn, som den Guds Mand havde givet ved Herrens Ord.',
        6: 'Da svarede Kongen og sagde til den Guds Mand: Kære, bed ydmygeligt for Herren din Guds Ansigt, og bed for mig, at min Haand maa komme tilbage til mig igen. Da bad den Guds Mand ydmygeligt for Herrens Ansigt, og Kongens Haand kom tilbage til ham og blev, som den var tilforn.',
        7: 'Og Kongen sagde til den Guds Mand: Kom hjem med mig, og vederkvæg dig, og jeg vil give dig en Gave.',
        8: 'Men den Guds Mand sagde til Kongen: Dersom du vilde give mig Halvdelen af dit Hus, gaar jeg dog ikke med dig, og jeg vil ikke æde Brød og ikke drikke Vand paa dette Sted.',
        9: 'Thi det er mig saa budet ved Herrens Ord og sagt: Du skal ikke æde Brød og ej drikke Vand, og du skal ikke vende tilbage ad den Vej, paa hvilken du kom.',
        10: 'Og han gik bort ad en anden Vej og vendte ikke tilbage ad den Vej, som han var kommen til Bethel.',
        11: 'Og der boede en gammel Profet i Bethel, og hans Søn kom og fortalte ham al den Gerning, som den Guds Mand gjorde den Dag i Bethel, de Ord, som han talte til Kongen, og de fortalte deres Fader dem.',
        12: 'Og deres Fader sagde til dem: Hvor er den Vej, han gik ad? thi hans Sønner havde set Vejen, ad hvilken den Guds Mand, som var kommen fra Juda, gik bort.',
        13: 'Da sagde han til sine Sønner: Sadler mig Asenet; og de sadlede Asenet til ham, og han red derpaa.',
        14: 'Og han drog efter den Guds Mand og fandt ham siddende under Egen og sagde til ham: Er du den Guds Mand, som kom fra Juda? og han sagde: Ja.',
        15: 'Da sagde han til ham: Kom hjem med mig og æd Brød!',
        16: 'Og han sagde: Jeg kan ikke vende tilbage med dig og komme med dig, jeg vil hverken æde Brød, ej heller drikke Vand med dig paa dette Sted.',
        17: 'Thi der skete et Ord til mig ved Herrens Ord: Du skal hverken æde Brød, ej heller drikke Vand der, du skal ikke vende tilbage, at gaa ad den Vej, paa hvilken du kom.',
        18: 'Og han sagde til ham: Jeg er og en Profet som du, og en Engel talte med mig ved Herrens Ord og sagde: Før ham tilbage med dig til dit Hus, at han æder Brød og drikker Vand; men han løj for ham.',
        19: 'Og han vendte tilbage med ham, og han aad Brød i hans Hus og drak Vand.',
        20: 'Og det skete, der de sade til Bords, da skete Herrens Ord til Profeten, som havde ført ham tilbage,',
        21: 'og han raabte til den Guds Mand, som var kommen fra Juda, og sagde: Saa sagde Herren: Fordi du har været genstridig imod Herrens Mund og ikke har holdt det Bud, som Herren din Gud bød dig,',
        22: 'men du vendte tilbage og aad Brød og drak Vand paa det Sted, om hvilket jeg sagde dig: Du skal hverken æde Brød, ej heller drikke Vand: Derfor skal dit Legeme ikke komme til dine Fædres Grav.',
        23: 'Og det skete, efter at han havde ædt Brød, og efter at han havde drukket, da sadlede han Asenet til ham, nemlig til Profeten, som han havde ført tilbage.',
        24: 'Saa drog han bort, og en Løve mødte ham paa Vejen og dræbte ham; og hans Legeme var kastet paa Vejen, og Asenet stod hos det, og Løven stod hos Legemet.',
        25: 'Og se, Folket som gik der forbi og saa Legemet kastet paa Vejen og Løven staa hos Legemet, de kom og sagde det i Staden, som den gamle Profet boede udi.',
        26: 'Der Profeten, som havde ført ham tilbage af Vejen, hørte det, da sagde han: Det er den Guds Mand, som var genstridig imod Herrens Mund, derfor gav Herren ham til Løven, og den sønderrev ham og dræbte ham efter Herrens Ord, som han talte til ham.',
        27: 'Og han talte til sine Sønner og sagde: Sadler mig Asenet; og de sadlede det.',
        28: 'Og han drog hen og fandt hans Legeme kastet paa Vejen og Asenet og Løven staaende hos Legemet; Løven havde ikke ædt Legemet og ikke sønderrevet Asenet.',
        29: 'Da tog Profeten den Guds Mands Legeme op og lagde det paa Asenet og førte det tilbage; saa kom den gamle Profet til Staden for at begræde og begrave ham.',
        30: 'Og han lagde hans Legeme i sin egen Grav, og de begræd ham, sigende: Ak, min Broder!',
        31: 'Og det skete, efter at han havde begravet ham, da sagde han til sine Sønner: Naar jeg dør, da skulle I begrave mig i Graven, i hvilken den Guds Mand er begraven: Lægger mine Ben hos hans Ben!',
        32: 'Thi det Ord skal vist ske, som han raabte efter Herrens Ord imod Alteret, som er i Bethel, og imod alle Huse paa Højene, som ere i Samarias Stæder.',
        33: 'Efter denne Handel vendte Jeroboam ikke om fra sin onde Vej; men han vendte om og gjorde Højenes Præster af Folket i Flæng; hvem der havde Lyst, hans Haand fyldte han, og de bleve Præster paa Højene.',
        34: 'Og denne Gerning blev Jeroboams Hus til Synd, saa at det skulde udslettes og udryddes af Jorderige.',
    },
    14: {
        1: 'Paa samme Tid blev Abia, Jeroboams Søn, syg.',
        2: 'Og Jeroboam sagde til sin Hustru: Kære, gør dig rede og forklæd dig, at de ikke skulle kende, at du er Jeroboams Hustru, og gak til Silo; se, der er Ahia, Profeten, han talte til mig, at jeg skulde være Konge over dette Folk.',
        3: 'Og du skal tage ti Brød og Kager med dig og en Krukke med Honning og gaa til ham; han skal kundgøre dig, hvad der skal vederfares Drengen.',
        4: 'Og Jeroboams Hustru gjorde saa og gjorde sig rede og gik til Silo og kom til Ahias Hus, og Ahia kunde ikke se, thi hans Øjne vare dunkle af hans høje Alder.',
        5: 'Men Herren havde sagt til Ahia: Se, Jeroboams Hustru kommer at udspørge dig i en Sag om sin Søn, thi han er syg; saa og saa skal du tale til hende, og det skal ske, naar hun kommer, da vil hun anstille sig fremmed.',
        6: 'Og det skete, der Ahia hørte hendes Fødders Lyd, da hun gik ind ad Døren, da sagde han: Kom ind, Jeroboams Hustru! hvi anstiller du dig fremmed? thi jeg er sendt til dig med et haardt Budskab.',
        7: 'Gak, sig til Jeroboam: Saa sagde Herren, Israels Gud: Fordi jeg har ophøjet dig midt af Folket og sat dig til en Fyrste over mit Folk Israel,',
        8: 'og jeg har revet Riget fra Davids Hus og givet dig det, og du har ikke været som min Tjener David, som holdt mine Bud, og som vandrede efter mig af sit ganske Hjerte til at gøre alene, hvad ret var for mine Øjne;',
        9: 'men du har gjort ilde fremfor alle, som have været før dig, og du er gaaet hen og har gjort dig andre Guder og støbte Billeder til at opirre mig og har kastet mig bag din Ryg:',
        10: "Se, derfor vil jeg føre Ulykke over Jeroboams Hus, og jeg vil udrydde af Jeroboams enhver, som er af Mandkøn, baade den bundne og den løsladte i Israel, og borttage Jeroboams Hus's Efterkommere, ligesom man borttager Skarnet, indtil det er aldeles ude med ham.",
        11: 'Den af Jeroboams, som dør i Staden, skulle Hundene æde, og den, der dør paa Marken, skulle Himmelens Fugle æde; thi Herren har talt det.',
        12: 'Saa gør du dig rede, gak til dit Hus; naar dine Fødder komme ind i Staden, da skal Barnet dø.',
        13: 'Og al Israel skal begræde ham, og de skulle begrave ham, thi denne aleneste skal komme i Graven af Jeroboams, fordi der er noget godt fundet hos ham, for Herren Israels Gud, i Jeroboams Hus.',
        14: 'Og Herren skal oprejse sig en Konge over Israel, som skal udrydde Jeroboams Hus paa samme Dag; og hvad om det alt nu sker?',
        15: 'Og Herren skal slaa Israel, ligesom Røret bevæges i Vandet, og oprykke Israel af dette gode Land, som han gav deres Fædre, og bortstrø dem paa hin Side Floden, fordi de gjorde sig Astartebilleder og opirrede Herren.',
        16: 'Og han skal overgive Israel for Jeroboams Synders Skyld, med hvilke han forsyndede sig, og kom Israel til at synde.',
        17: 'Da gjorde Jeroboams Hustru sig rede og gik og kom til Thirza; der hun kom paa Dørtærskelen af Huset, da døde Drengen.',
        18: 'Og de begrove ham, og al Israel begræd ham, efter Herrens Ord, som han talte ved sin Tjener Ahia, Profeten.',
        19: 'Men det øvrige af Jeroboams Handeler, hvorledes han stred, og hvorledes han regerede, se, de Ting ere skrevne i Israels Kongers Krønikers Bog.',
        20: 'Men de Dage, i hvilke Jeroboam var Konge, ere to og tyve Aar, og han laa med sine Fædre, og hans Søn, Nadab, blev Konge i hans Sted.',
        21: 'Og Roboam, Salomos Søn, var Konge i Juda; Roboam var et og fyrretyve Aar gammel, der han blev Konge, og regerede sytten Aar i Jerusalem, den Stad, som Herren havde udvalgt af alle Israels Stammer til at sætte sit Navn der; og hans Moders Navn var Naema, den ammonitiske.',
        22: 'Og Juda gjorde det onde for Herrens Øjne, og de opvakte hans Nidkærhed langt mere, end deres Fædre havde gjort, med deres Synder, hvormed de syndede.',
        23: 'Thi ogsaa de opførte sig Høje og Støtter og Astartebilleder paa hver ophøjet Høj og under hvert grønt Træ.',
        24: 'Og der var ogsaa Skørlevnere i Landet, de gjorde efter alle de Hedningers Vederstyggeligheder, som Herren havde fordrevet fra Israels Børns Ansigt.',
        25: 'Og det skete i Kong Roboams femte Aar, at Sisak, Kongen af Ægypten, drog op imod Jerusalem.',
        26: 'Og han tog Liggendefæet i Herrens Hus og Liggendefæet i Kongens Hus og borttog alle Ting og tog alle de Skjolde af Guld, som Salomo havde ladet gøre.',
        27: 'Og Kong Roboam lod gøre Kobberskjolde i deres Sted og betroede dem i de øverste Drabanters Haand, som toge Vare paa Døren for Kongens Hus.',
        28: 'Og det skete, saa tidt Kongen gik ind i Herrens Hus, bare Drabanterne dem frem, og de bare dem tilbage i Drabanternes Kammer.',
        29: 'Men det øvrige af Roboams Handeler og alt det, han gjorde, ere de Ting ikke skrevne i Judas Kongers Krønikers Bog?',
        30: 'Og der var Krig imellem Roboam og imellem Jeroboam alle Dagene.',
        31: 'Og Roboam laa med sine Fædre og blev begraven hos sine Fædre i Davids Stad, og hans Moders Navn var Naema, den ammonitiske; og Abiam, hans Søn, blev Konge i hans Sted.',
    },
    15: {
        1: 'Og i det attende Kong Jeroboams, Nebats Søns, Aar blev Abiam Konge over Juda.',
        2: 'Han regerede tre Aar i Jerusalem, og hans Moders Navn var Maeka, Abisaloms Datter.',
        3: 'Og han vandrede i alle sin Faders Synder, som han gjorde før ham, og hans Hjerte var ikke helt med Herren hans Gud, som Davids, hans Faders, Hjerte.',
        4: 'Men Herren hans Gud gav ham et Lys i Jerusalem for Davids Skyld, ved at han oprejste hans Søn efter ham og lod Jerusalem bestaa;',
        5: 'fordi David gjorde det, som ret var for Herrens Øjne, og veg ikke fra alt det, som han bød ham, alle sine Livs Dage, uden i den Handel med Hethiteren Uria.',
        6: 'Og der var Krig imellem Roboam og imellem Jeroboam alle hans Livs Dage.',
        7: 'Men det øvrige af Abiams Handeler og alt det, som han har gjort, ere de Ting ikke skrevne i Judas Kongers Krønikers Bog? Og der var Krig imellem Abiam og Jeroboam.',
        8: 'Og Abiam laa med sine Fædre, og de begrove ham i Davids Stad, og Asa, hans Søn, blev Konge i hans Sted.',
        9: 'Og i det tyvende Jeroboams, Israels Konges, Aar blev Asa Konge over Juda.',
        10: 'Og han regerede et og fyrretyve Aar i Jerusalem, og hans Moders Navn var Maeka, Abisaloms Datter.',
        11: 'Og Asa gjorde det, som ret var for Herrens Øjne, som David hans Fader.',
        12: 'Og han fordrev Skørlevnerne af Landet og bortskaffede alle stygge Afguder, som hans Fædre havde gjort.',
        13: 'Tilmed afsatte han Maeka, sin Moder, at hun ikke skulde være Dronning, fordi hun havde gjort sig et grueligt Billede af Astarte, og Asa udryddede hendes gruelige Billede og opbrændte det ved Kedrons Bæk.',
        14: 'Men Højene toges ikke bort; dog var Asas Hjerte helt med Herren alle hans Dage.',
        15: 'Og ban førte de Ting, som hans Fader havde helliget, og hvad som han selv havde helliget, ind i Herrens Hus, Sølv og Guld og Kar.',
        16: 'Og der var Krig mellem Asa og Baesa, Israels Konge, alle deres Dage.',
        17: 'Thi Baesa, Israels Konge, drog op imod Juda og byggede Rama, for ikke at tilstede Asa, Judas Konge, at nogen drog ud eller kom ind.',
        18: "Da tog Asa alt det Sølv og Guld, de Ting, som vare blevne tilovers af Herrens Hus's Liggendefæ og af Kongens Hus's Liggendefæ, og gav sine Tjenere dem i Hænderne, og Kong Asa sendte dem til Benhadad, en Søn af Tabrimmon, Hesions Søn, Kongen i Syrien, som boede i Damaskus og lod sige:",
        19: 'Der er en Pagt imellem mig og imellem dig, imellem min Fader og imellem din Fader, se, jeg sender dig Skænk, Sølv og Guld, drag hen, gør til intet din Pagt med Baesa, Israels Konge, at han maa drage op fra mig.',
        20: 'Og Benhadad adlød Kong Asa og sendte de Hærførere, som han havde, imod Israels Stæder og slog Ijon og Dan og Abel-Beth-Maaka og hele Kinneroth, tillige med alt Nafthalis Land.',
        21: 'Og det skete, der Baesa hørte det, da lod han af fra at bygge Rama og blev i Thirza.',
        22: 'Saa lod Kong Asa hele Juda opbyde, der blev ingen fri, og de toge Stenene bort af Rama tillige med Tømmeret der, som Baesa havde bygget med, og Kong Asa byggede dermed Geba i Benjamin og Mizpa.',
        23: 'Men det øvrige af alle Asas Han deler og al hans Vælde og alt, hvad han har gjort, og de Stæder, som han har bygget, ere de Ting ikke skrevne i Judas Kongers Krønikers Bog? Dog i sin Alderdoms Tid blev han syg i sine Fødder.',
        24: 'Og Asa laa med sine Fædre og blev begraven med sine Fædre i Davids, sin Faders Stad, og Josafat, hans Søn, blev Konge i hans Sted.',
        25: 'Og Nadab, Jeroboams Søn, blev Konge over Israel i det andet Asas, Judas Konges, Aar og regerede over Israel to Aar.',
        26: 'Og han gjorde det onde for Herrens Øjne og vandrede i sin Faders Veje og i hans Synd, som han kom Israel til at synde med.',
        27: 'Men Baesa, Ahias Søn, af Isaskars Hus, gjorde et Forbund imod ham, og Baesa slog ham ved Gibbethon, som hørte Filisterne til, der Nadab og al Israel belejrede Gibbethon.',
        28: 'Og Baesa slog ham ihjel i det tredje Asas, Judas Konges, Aar og blev Konge i hans Sted.',
        29: 'Og det skete, der han var Konge, da slog han hele Jeroboams Hus, han lod ikke nogen af Jeroboams blive tilovers, som havde Aande, indtil han havde ødelagt ham, efter Herrens Ord, som han talte ved Siloniteren Ahia, sin Tjener,',
        30: 'for Jeroboams Synders Skyld, som han syndede med, og som han kom Israel til at synde med, og for den Opirrelse, med hvilken han opirrede Herren, Israels Gud.',
        31: 'Men det øvrige af Nadabs Handeler, og alt det, som han har gjort, ere de Ting ikke skrevne i Israels Kongers Krønikers Bog?',
        32: 'Og der var Krig imellem Asa og imellem Baesa, Israels Konge, alle deres Dage.',
        33: 'I det tredje Asas, Judas Konges, Aar blev Baesa, Ahias Søn, Konge over al Israel i Thirza, fire og tyve Aar.',
        34: 'Og han gjorde det onde for Her-Tens Øjne og vandrede i Jeroboams Vej og i hans Synd, som han kom Israel til at synde med.',
    },
    16: {
        1: 'Og Herrens Ord skete til Jehu, Hananis Søn, imod Baesa saaledes:',
        2: 'Fordi jeg ophøjede dig af Støvet og satte dig til en Fyrste over mit Folk Israel, og du vandrede i Jeroboams Vej og kom mit Folk Israel til at synde, til at opirre mig med deres Synder:',
        3: "Se, saa borttager jeg Baesas Efterkommere og hans Hus's Efterkommere, og jeg vil gøre ved dit Hus ligesom ved Jeroboams, Nebats Søns, Hus.",
        4: 'Den, som dør af Baesas i Staden, skulle Hundene æde, og den, der dør af hans paa Marken, skulle Himmelens Fugle æde.',
        5: 'Men det øvrige af Baesas Handeler, og hvad han har gjort, og hans Vælde, ere de Ting ikke skrevne i Israels Kongers Krønikers Bog?',
        6: 'Og Baesa laa med sine Fædre og blev begraven i Thirza, og hans Søn Ela blev Konge i hans Sted.',
        7: 'Saa skete ogsaa Herrens Ord ved Jehu, Hananis Søn, Profeten, over Baesa og over hans Hus, baade for alt det onde, som han gjorde for Herrens Øjne til at opirre ham ved sine Hænders Gerning, saa at han blev ligesom Jeroboams Hus, og fordi han havde slaaet dette.',
        8: 'I det seks og tyvende Asas, Judas Konges, Aar blev Ela, Baesas Søn, Konge over Israel i Thirza, i to Aar.',
        9: 'Og hans Tjener Simri, Høvedsmand over Halvdelen af Vognene, gjorde et Forbund imod ham, medens han i Thirza drak og var drukken i Arzas Hus, som var Hovmester i Thirza.',
        10: 'Og Simri kom og slog ham og dræbte ham i det syv og tyvende Asas, Judas Konges, Aar, og blev Konge i hans Sted.',
        11: 'Og det skete, der han var bleven Konge, der han sad paa sin Trone, da slog han det ganske Baesas Hus, han lod ingen blive tilovers for ham af alt Mandkøn, hverken hans næste Slægtninge eller hans Venner.',
        12: 'Saa ødelagde Simri hele Baesas Hus, efter Herrens Ord, som han talte til Baesa ved Jehu, Profeten,',
        13: 'for alle Baesas Synders og Elas, hans Søns, Synders Skyld, hvormed de syndede, og hvormed de kom Israel til at synde, saa at de opirrede Herren Israels Gud ved deres Afguder.',
        14: 'Men det øvrige af Elas Handeler, og alt det, han har gjort, ere de Ting ikke skrevne i Israels Kongers Krønikers Bog?',
        15: 'I det syv og tyvende Asas, Judas Konges, Aar blev Simri Konge i Thirza i syv Dage; men Folket havde lejret sig imod Gibbethon, som var Filisternes.',
        16: 'Der Folket, som havde lejret sig der, hørte sige: Simri har gjort et Forbund og slaget Kongen ihjel, da gjorde al Israel paa den samme Dag Omri, Stridshøvedsmanden, til Konge over Israel i Lejren.',
        17: 'Og Omri drog op og al Israel med ham fra Gibbethon og belejrede Thirza.',
        18: "Og det skete, der Simri saa, at Staden var indtagen, da gik han ind i Kongens Hus's Palads og opbrændte over sig Kongens Hus med Ild og døde",
        19: 'for sine Synders Skyld, hvormed han havde forsyndet sig, idet han gjorde det onde for Herrens Øjne og vandrede i Jeroboams Vej og i hans Synd, som han forsyndede sig med, og hvormed han bragte Israel til at synde.',
        20: 'Men det øvrige af Simris Handeler og hans Forbund, som han stiftede, ere de Ting ikke skrevne i Israels Kongers Krønikers Bog?',
        21: 'Da delte Israels Folk sig i to Dele, Halvdelen af Folket holdt med Thibni, Ginaths Søn, for at gøre ham til Konge, og Halvdelen holdt med Omri.',
        22: 'Men det Folk, som holdt med Omri, blev stærkere end det Folk, som holdt med Thibni, Ginaths Søn; og Thibni døde, og Omri blev Konge.',
        23: 'I det et og tredivte Asas, Judas Konges, Aar blev Omri Konge over Israel i tolv Aar; i Thirza regerede han i seks Aar.',
        24: 'Og han købte Samarias Bjerg af Semer for to Centner Sølv og byggede paa Bjerget og kaldte Stadens Navn, som han byggede, efter Semers Navn, som havde været Herre over Bjerget, Samaria.',
        25: 'Og Omri gjorde det onde for Herrens Øjne, ja han gjorde ondt fremfor alle, som havde været før ham.',
        26: 'Og han vandrede i al Jeroboams, Nebats Søns, Vej og i hans Synder, hvormed han kom Israel til at synde, saa at de opirrede Herren, Israels Gud med deres Afguder.',
        27: 'Men det øvrige af Omris Handeler, hvad han gjorde, og hans Magt, hvilken han skaffede sig, ere de Ting ikke skrevne i Israels Kongers Krønikers Bog?',
        28: 'Og Omri laa med sine Fædre og blev begraven i Samaria, og Akab, hans Søn, blev Konge i hans Sted.',
        29: 'Og i det otte og tredivte Asas, Judas Konges, Aar blev Akab, Omris Søn, Konge over Israel, og Akab, Omris Søn, regerede over Israel i Samaria to og tyve Aar.',
        30: 'Og Akab, Omris Søn, gjorde det onde for Herrens Øjne fremfor alle, som havde været før ham.',
        31: 'Og det skete, som var det ham for lidet, at han vandrede i Jeroboams, Nebats Søns, Synder, at han tog til Hustru Jesabel, Eth-Baals, Zidoniernes Konges Datter, og han gik hen og tjente Baal og tilbad ham.',
        32: 'Og han oprejste Baal et Alter i Baals Hus, som han byggede i Samaria.',
        33: 'Akab gjorde og Astartebilledet, og Akab gjorde mere til at opirre Herren, Israels Gud, end alle Israels Konger, som vare før ham.',
        34: 'I hans Dage byggede Betheliteren Hiel Jeriko; det kostede ham Abiram, hans førstefødte Søn, der han lagde dens Grundvold, og Segub, hans yngste Søn, der han satte dens Porte, efter Herrens Ord, som han havde talet ved Josva, Nuns Søn.',
    },
    17: {
        1: 'Og Thisbiteren Elias, en af dem, som boede i Gilead, sagde til Akab: Saa vist som Herren, Israels Gud, lever, for hvis Ansigt jeg staar, skal der hverken komme Dug eller Regn i disse Aar, uden efter mit Ord.',
        2: 'Og Herrens Ord skete til ham og sagde:',
        3: 'Gak herfra og vend dig imod Østen og skjul dig ved Bækken Krith, som er lige over for Jordanen.',
        4: 'Og det skal ske, at du skal drikke af Bækken, og jeg har budet Ravnene, at de skulle forsørge dig der.',
        5: 'Og han gik og gjorde efter Herrens Ord og gik og blev ved Bækken Krith, som er lige over for Jordanen.',
        6: 'Og Ravnene bragte ham Brød og Kød om Morgenen og Brød og Kød om Aftenen, og han drak af Bækken.',
        7: 'Og det skete efter en Tids Forløb, da blev Bækken tør, thi der var ikke Regn i Landet.',
        8: 'Da skete Herrens Ord til ham og sagde:',
        9: 'Staa op og gak til Sarepta, som er ved Sidon, og bliv der; se, jeg har budet der en Enke, at hun skal forsørge dig.',
        10: 'Og han stod op og gik til Sarepta og kom til Stadsporten, og se, der var en Enke, som sankede Ved; og han kaldte ad hende og sagde: Kære, hent mig lidt Vand i Karret, at jeg kan drikke.',
        11: 'Da gik hun at hente, og han kaldte ad hende og sagde: Kære, tag mig et Stykke Brød med i din Haand.',
        12: 'Men hun sagde: Saa vist som Herren din Gud lever, jeg har ikke en Kage, kun en Haandfuld Mel i en Krukke og lidet Olie i et Krus; og se, jeg sanker et Par Stykker Brænde og gaar ind og vil lave det til mig og til min Søn, at vi maa æde det og dø.',
        13: 'Og Elias sagde til hende: Frygt ikke, gak ind, gør det efter dine Ord; dog lav mig først en liden Kage deraf og bring mig den ud, siden skal du lave dig og din Søn noget.',
        14: 'Thi saa siger Herren, Israels Gud: Melet i Krukken skal ikke fortæres, og Oliekruset skal ikke blive tomt indtil den Dag, at Herren skal give Regn over Jorderige.',
        15: "Og hun gik og gjorde efter Elias's Ord; og hun aad, ja, han og hun og hendes Hus i en god Tid.",
        16: 'Melet i Krukken blev ikke fortæret, og Oliekruset blev ikke tomt, efter Herrens Ord, som han talte ved Elias.',
        17: 'Og det skete efter disse Handeler, at samme Kvindes, Husets Ejerindes, Søn blev syg, og hans Sygdom var saare svar, indtil der ikke mere var Aande i ham.',
        18: 'Og hun sagde til Elias: Hvad har jeg at gøre med dig, du Guds Mand? du er kommen til mig at lade min Misgerning kommes i Hu og at dræbe min Søn.',
        19: 'Og han sagde til hende: Giv mig hid din Søn; og han tog ham af hendes Skød og bar ham op paa Salen, hvor han boede, og han lagde ham paa sin Seng,',
        20: 'og han raabte til Herren og sagde: Herre, min Gud! har du virkelig bragt Ulykke over denne Enke, som jeg opholder mig hos, saa at du dræber hendes Søn?',
        21: 'Saa udstrakte han sig over Barnet tre Gange og raabte til Herren og sagde: Herre, min Gud! Kære, lad dette Barns Sjæl komme inden i det igen!',
        22: "Og Herren hørte Elias's Røst, og Barnets Sjæl kom inden i det igen, og det blev levende.",
        23: 'Og Elias tog Barnet og førte det ned fra Salen i Huset og gav hans Moder det, og Elias sagde: Se, din Søn lever.',
        24: 'Og Kvinden sagde til Elias: Nu ved jeg dette, at du er en Guds Mand, og at Herrens Ord i din Mund er Sandhed.',
    },
    18: {
        1: 'Og det skete mange Dage derefter, at Herrens Ord skete til Elias i det tredje Aar og sagde: Gak, lad dig se for Akab, saa vil jeg give Regn paa Jorderige.',
        2: 'Elias gik for at lade sig se for Akab. Og Hungeren var svar i Samaria.',
        3: 'Og Akab havde kaldet ad Obadias, som var Hovmester; (men Obadias frygtede Herren saare;',
        4: 'thi det skete, der Jesabel udryddede Herrens Profeter, at Obadias tog hundrede Profeter og skjulte dem, halvtredsindstyve Mænd i hver Hule, og forsørgede dem med Brød og Vand);',
        5: 'og Akab havde sagt til Obadias: Drag igennem Landet til alle Vandkilder og til alle Bække, maaske vi kunne finde Græs og beholde Hestene og Mulerne i Live, at ikke Kvæget omkommer for os.',
        6: 'Og de delte Landet imellem sig for at drage igennem det; Akab drog alene paa en Vej, og Obadias drog alene paa en anden Vej.',
        7: 'Men det skete, der Obadias var paa Vejen, se, da mødte Elias ham, og han kendte ham og faldt paa sit Ansigt og sagde: Er det dig, min Herre Elias?',
        8: 'Han sagde til ham: Det er mig; gak, sig til din Herre: Se, Elias er her!',
        9: 'Og han sagde: Hvad har jeg syndet, at du vil give din Tjener i Akabs Hænder, at han skal dræbe mig?',
        10: 'Saa vist som Herren din Gud lever, der er intet Folk eller Rige, til hvilket min Herre jo har sendt hen, for der at lede efter dig, og de sagde: Han er ikke her; og han tog en Ed af det Rige og det Folk, at man ikke havde fundet dig.',
        11: 'Og du siger nu: Gak, sig din Herre: Se, Elias er her!',
        12: 'Og det maatte ske, naar jeg gik fra dig, at Herrens Aand tog dig bort, jeg ved ikke hvorhen, og jeg kom at give Akab det til Kende, og han fandt dig ikke, da slog han mig ihjel; men din Tjener frygter dog Herren fra sin Ungdom af.',
        13: 'Er det ikke givet min Herre til Kende, hvad jeg gjorde, der Jesabel slog Herrens Profeter ihjel, at jeg skjulte hundrede Mænd af Herrens Profeter, her halvtredsindstyve og der halvtredsindstyve Mænd i en Hule, og forsørgede dem med Brød og Vand?',
        14: 'Og du siger nu: Gak, sig din Herre: Se, Elias er her! og han vil slaa mig ihjel.',
        15: 'Og Elias sagde: Saa vist som Herren Zebaoth lever, for hvis Ansigt jeg staar, i Dag vil jeg lade mig se for ham.',
        16: 'Da gik Obadias Akab i Møde og gav ham det til Kende, og Akab gik Elias i Møde.',
        17: 'Og det skete, der Akab saa Elias, da sagde Akab til ham: Er det dig, som forstyrrer Israel?',
        18: 'Da sagde han: Ikke jeg har forstyrret Israel, men du og din Faders Hus, idet I forlode Herrens Bud, og du vandrede efter Baalerne.',
        19: 'Men nu sende du Bud og samle al Israel til mig til Karmels Bjerg, samt de fire Hundrede og halvtredsindstyve Baals Profeter og de fire Hundrede Astartes Profeter, som æde af Jesabels Bord.',
        20: 'Saa sendte Akab hen iblandt alle Israels Børn og samlede Profeterne til Karmels Bjerg.',
        21: 'Da gik Elias frem til alt Folket og sagde: Hvor længe ville I halte til begge Sider? dersom Herren er Gud, da vandrer efter ham, men dersom Baal er det, saa vandrer efter ham! Men Folket svarede ham ikke et Ord.',
        22: 'Da sagde Elias til Folket: Jeg er ene tilbage som Herrens Profet; men Baals Profeter ere fire Hundrede og halvtredsindstyve Mænd.',
        23: 'Saa lader dem give os to Okser, og de maa udvælge sig den ene Okse og hugge den i Stykker og lægge den paa Veddet, men ikke lægge Ud dertil, saa vil jeg lave den anden Okse til og lægge den paa Veddet, men ikke lægge Ild dertil.',
        24: 'Saa kalder paa eders Guds Navn, og jeg vil kalde paa Herrens Navn, og det skal ske: Den Gud, som svarer ved Ilden, han er Gud; og alt Folket svarede og sagde: Det Ord er godt.',
        25: 'Og Elias sagde til Baals Profeter: Udvælger eder den ene Okse og laver den først til, thi I ere de mange, og kalder paa eders Guds Navn, men lægger ikke Ild dertil.',
        26: 'Og de toge Oksen, som han gav dem, og lavede den til og kaldte paa Baals Navn, fra Morgenen og indtil Middagen, og sagde: O Baal! bønhør os! Men der var ingen Røst og ej heller nogen, som svarede; og de gik haltende om Alteret, som man havde opført.',
        27: 'Og det skete om Middagen, da spottede Elias dem og sagde: Raaber med høj Røst, thi han er jo en Gud; thi han er vel falden i Tanker, eller er gaaet til Side eller er paa Rejse — maaske sover han — at han kan opvaagne.',
        28: 'Og de raabte med høj Røst og saarede sig efter deres Vis med Knive og med Syle, indtil Blodet flød ned over dem.',
        29: 'Og det skete, der Middagen var gaaet forbi, at de profeterede, indtil man skulde ofre Madofferet; og der var ingen Røst og ingen, som svarede, og ingen, som agtede derpaa.',
        30: 'Da sagde Elias til alt Folket: Kommer hid til mig! og alt Folket kom frem til ham, og han helede Herrens Alter, som var nedbrudt.',
        31: 'Og Elias tog tolv Stene, efter Jakobs Børns Stammers Tal, hans, til hvem Herrens Ord var sket, sigende: Dit Navn skal være Israel.',
        32: 'Og han byggede af de Stene et Alter i Herrens Navn, og han gjorde en Grav, saa rummelig som til to Maaders Udsæd, omkring Alteret.',
        33: 'Og han lagde Veddet til Rette og huggede Oksen i Stykker og lagde den paa Veddet.',
        34: 'Og han sagde: Fylder fire Krukker med Vand og øser det paa Brændofferet og paa Veddet; og han sagde: Gører det anden Gang, og de gjorde det anden Gang; og han sagde: Gører det tredje Gang, og de gjorde det tredje Gang.',
        35: 'Og Vandet løb trindt omkring Alteret, og han fyldte ogsaa Graven med Vand,',
        36: 'Og det skete, ved den Tid man ofrer Madofferet, da traadte Profeten Elias frem og sagde: Herre, Abrahams, Isaks og Israels Gud! lad det kendes i Dag, at du er Gud i Israel, og at jeg er din Tjener, og at jeg har gjort alle disse Gerninger efter dit Ord.',
        37: 'Bønhør mig, Herre! bønhør mig, at dette Folk maa vide, at du, Herre, du er Gud, og at du har vendt deres Hjerter tilbage.',
        38: 'Da faldt Herrens Ild ned og fortærede Brændofferet og Veddet og Stenene og Støvet og slikkede Vandet op, som var i Graven.',
        39: 'Og alt Folket saa det og faldt ned paa deres Ansigt og sagde: Herren, han er Gud! Herren, han er Gud!',
        40: 'Da sagde Elias til dem: Griber Baals Profeter, at ingen Mand undkommer af dem; og de grebe dem, og Elias førte dem ned til Kisons Bæk og nedhuggede dem der.',
        41: 'Og Elias sagde til Akab: Drag op, æd og drik; thi der høres en Susen af megen Regn.',
        42: 'Og Akab drog op for at æde og at drikke; og Elias gik op paa Karmels Top og bøjede sig imod Jorden og satte sit Ansigt ned imellem sine Knæ.',
        43: 'Og han sagde til sin Dreng: Kære, gak op, se ud ad Vejen til Havet; og han gik op og saa til og sagde: Der er ikke noget; og han sagde: Gak igen derhen, syv Gange.',
        44: 'Og det skete den syvende Gang, at han sagde: Se, en liden Sky stiger op fra Havet, som en Mands Haand; og han sagde: Gak op, sig til Akab: Spænd for og far ned, at Regnen ikke skal opholde dig.',
        45: 'Og det skete i en Haandevending, da blev Himmelen sort af Skyer og Vejr, og der kom en stor Regn; men Akab for af Sted og drog til Jisreel.',
        46: 'Og Herrens Haand var over Elias, og han ombandt sig om sine Lænder og løb frem foran Akab, lige til Jisreel.',
    },
    19: {
        1: 'Og Akab fortalte Jesabel om alt det, som Elias havde gjort, og om alle dem, han havde ihjelslaget med Sværdet, nemlig alle Profeterne.',
        2: 'Da sendte Jesabel et Bud til Elias og lod sige: Guderne gøre mig nu og fremdeles saa og saa, om jeg ikke i Morgen paa denne Tid gør imod din Sjæl, ligesom der er gjort imod en af disses Sjæle.',
        3: 'Der han saa det, da stod han op og gik bort for at redde sit Liv og kom til Beersaba, som tilhører Juda; og han lod sin Dreng blive der.',
        4: 'Og han gik selv i Ørken en Dags Rejse og kom og satte sig under et Enebærtræ; og han ønskede sig Døden og sagde: Det er nok, tag nu min Sjæl, Herre! thi jeg er ikke bedre end mine Fædre.',
        5: 'Saa lagde han sig og sov under et Enebærtræ; og se, der var en Engel, som rørte ved ham og sagde til ham: Staa op, æd!',
        6: 'Og han saa til, og se, ved hans Hovedgærde var en Kage, bagt paa Gløder, og en Krukke med Vand; saa aad og drak han og lagde sig igen.',
        7: 'Og Herrens Engel kom anden Gang igen og rørte ved ham og sagde: Staa op, æd; thi Vejen er for lang for dig.',
        8: 'Og han stod op og aad og drak, og han gik ved den samme Mads Kraft i fyrretyve Dage og fyrretyve Nætter indtil Guds Bjerg Horeb.',
        9: 'Og der gik han ind i en Hule og blev der om Natten; og se, Herrens Ord kom til ham og sagde til ham: Hvad har du her at gøre, Elias?',
        10: 'Og han sagde: Jeg har været nidkær for Herren Zebaoths Gud, fordi Israels Børn have forladt din Pagt, de have nedbrudt dine Altre og slaget dine Profeter ihjel med Sværd; og jeg alene er bleven tilovers, og de søge efter mit Liv for at tage det fra mig.',
        11: 'Og han sagde: Gak ud, og du skal staa ved Bjerget for Herrens Ansigt; og se, Herren gik forbi, og et stort og stærkt Vejr, som sønderrev Bjergene og sønderbrød Klipperne for Herrens Ansigt: Herren var ikke i Vejret; og der kom et Jordskælv efter Vejret: Herren var ikke i Jordskælvet.',
        12: 'Og efter Jordskælvet kom en Ild: Herren, var ikke i Ilden; men efter Ilden kom der en stille, sagte Lyd.',
        13: 'Og det skete, der Elias hørte det, da tilhyllede han sit Ansigt med sin Kappe og gik ud og stod i Døren paa Hulen, og se, da kom der en Røst til ham og sagde: Hvad har du her at gøre, Elias?',
        14: 'Og han sagde: Jeg har været nidkær for Herren Zebaoths Gud, fordi Israels Børn have forladt din Pagt, nedbrudt dine Altre og ihjelslaget dine Profeter med Sværd, og jeg alene er bleven tilovers, og de søge efter mit Liv for at tage det fra mig.',
        15: 'Og Herren sagde til ham: Gak, vend tilbage ad din Vej igennem Ørken til Damaskus, og du skal gaa ind og salve Hasael til Konge over Syrien;',
        16: 'og du skal salve Jehu, Nimsis Søn, til Konge over Israel og salve Elisa, Safats Søn fra Abel-Mehola, til Profet i dit Sted:',
        17: 'Og det skal ske, at hvo som undkommer fra Hasaels Sværd, den skal Jehu ihjelslaa, og hvo som undkommer fra Jehus Sværd, den skal Elisa ihjelslaa.',
        18: 'Og jeg har ladet syv Tusinde blive tilovers i Israel, nemlig alle Knæ, som ikke have bøjet sig for Baal, og hver Mund, som ikke har kysset ham.',
        19: 'Saa gik han derfra og fandt Elisa, Safats Søn, der pløjede med tolv Spand Øksne foran sig, og han selv var med det tolvte; og Elias gik over til ham og kastede sin Kappe paa ham.',
        20: 'Og han forlod Øksnene og løb efter Elias og sagde: Kære, lad mig kysse min Fader og min Moder, saa vil jeg følge dig! og han sagde til ham: Gak, kom igen, thi hvad har jeg gjort dig?',
        21: 'Saa gik han fra ham igen, og han tog et Spand Øksne og ofrede dem og kogte deres Kød ved Tøjet paa Øksnene og gav Folket, og de aade; og han stod op og fulgte Elias og tjente ham.',
    },
    20: {
        1: 'Og Benhadad, Kongen i Syrien samlede hele sin Hær, og der var to og tredive Konger med ham og Heste og Vogne; og han drog op og belejrede Samaria og stred imod den.',
        2: 'Og han sendte Bud til Akab, Israels Konge, til Staden.',
        3: 'Og han lod ham sige: Saa siger Benhadad: Dit Sølv og dit Guld, det er mit, og dine smukkeste Hustruer og Børn, de ere mine.',
        4: 'Og Israels Konge svarede og sagde: Efter dine Ord skal det være, min Herre Konge! jeg er din og alt det, jeg har.',
        5: 'Derefter kom Budene igen og sagde: Saa siger Benhadad: Efterdi jeg sendte til dig og lod sige: Du skal give mig dit Sølv og dit Guld og dine Hustruer og dine Børn:',
        6: 'Saa vil jeg sende mine Tjenere til dig i Morgen paa denne Tid, og de skulle ransage i dit Hus og i dine Tjeneres Huse, og det skal ske, alt det, som er lysteligt for dine Øjne, skulle de lægge i deres Hænder og tage det bort.',
        7: 'Da kaldte Israels Konge ad alle Landets ældste og sagde: Kære, mærker og ser, at denne søger det, som ondt er; thi han sendte til mig om mine Hustruer og om mine Børn og om mit Sølv og om mit Guld, og jeg har ikke nægtet ham det.',
        8: 'Da sagde alle de ældste og alt Folket til ham: Du skal ikke adlyde og ikke samtykke.',
        9: 'Da sagde han til Benhadads Bud: Siger min Herre Kongen: Alt det, du sendte til din Tjener første Gang om, vil jeg gøre, men denne Gerning kan jeg ikke gøre, og Budene gik og bragte ham Svar igen.',
        10: 'Da sendte Benhadad til ham og lod sige: Guderne gøre mig nu og fremdeles saa og saa, om Støvet af Samaria skal blive nok til, at alt Folket, som er i Følge med mig, skal kunne føre hver en Haandfuld derfra.',
        11: 'Da svarede Israels Konge og sagde: Siger: Den, som ombinder Bæltet, skal ikke rose sig som den, der løser det.',
        12: 'Og det skete, der han hørte dette Ord, medens han drak, han og Kongerne i Teltene, da sagde han til sine Tjenere: Sætter an; og de satte an imod Staden.',
        13: 'Og se, en Profet gik frem til Akab, Israels Konge, og sagde: Saa sagde Herren: Har du set hele denne store Hob? se, jeg vil give den i Dag i din Haand, at du skal fornemme, at jeg er Herren.',
        14: 'Og Akab sagde: Ved hvem? og han sagde: Saa siger Herren: Ved Landshøvdingenes Drenge; og han sagde: Hvem skal begynde Striden? og han sagde: Du.',
        15: 'Saa talte han Landshøvdingenes Drenge, og de vare to Hundrede og to og tredive; og efter dem talte han hele Folket, alle Israels Børn, syv Tusinde.',
        16: 'Og de droge ud om Middagen; og Benhadad drak og var drukken i Teltene, han og Kongerne, nemlig de to og tredive Konger, som hjalp ham.',
        17: 'Og Landshøvdingenes Drenge droge først ud; og Benhadad sendte nogle hen, og de gave ham til Kende og sagde: Der drager Mænd ud fra Samaria.',
        18: 'Og han sagde: Dersom de ere uddragne for Freds Skyld, saa griber dem levende, og dersom de ere uddragne for Krigs Skyld, saa griber dem levende!',
        19: 'Da de vare uddragne af Staden, nemlig Landshøvdingenes Drenge og Hæren, som fulgte dem:',
        20: 'Da sloge de hver sin Mand, og Syrerne flyede, og Israel forfulgte dem; og Benhadad, Kongen af Syrien, undkom paa en Hest med Rytterne.',
        21: 'Og Israels Konge drog ud og slog Heste og Vogne og slog Syrerne med et stort Slag.',
        22: 'Da gik Profeten frem til Israels Konge og sagde til ham: Gak, forstærk dig, og vid og se, hvad du skal gøre; thi naar Aaret er omme, vil Kongen af Syrien drage op imod dig.',
        23: 'Og Kongen af Syriens Tjenere sagde til ham: Deres Guder ere Bjergenes Guder, derfor ere de stærkere end vi; men lader os stride imod dem paa det jævne Land; hvad gælder det, om vi ikke skulle blive stærkere end de?',
        24: 'Og gør denne Gerning: Tag Kongerne bort, hver fra sin Plads, og sæt Statholdere i deres Sted!',
        25: 'Og tæl dig en Hær, som denne Hær var, som er falden for dig, og Heste som de Heste og Vogne som de Vogne, og lader os stride imod dem paa det jævne Land; hvad gælder det, om vi ikke skulle blive stærkere end de? og han adlød deres Røst og gjorde saa.',
        26: 'Og det skete, der Aaret var omme, da talte Benhadad Syrerne og drog op til Afek, til Krigen imod Israel.',
        27: 'Og Israels Børn bleve talte og forsynede, og de droge imod dem; og Israels Børn lejrede sig imod dem som to smaa Gedehjorde; men Syrerne havde opfyldt Landet.',
        28: 'Og der kom en Guds Mand frem og talte til Israels Konge og sagde: Saa sagde Herren: Fordi Syrerne have sagt: Herren er Bjergenes Gud og ikke Dalenes Gud, derfor har jeg givet hele denne store Hob i din Haand, for at I skulle fornemme, at jeg er Herren.',
        29: 'Og disse lejrede sig over for dem syv Dage, og det skete paa den syvende Dag, da begyndte Slaget, og Israels Børn sloge Syrerne, hundrede Tusinde Fodfolk paa een Dag.',
        30: 'Og de, som bleve tilovers, flyede til Afek ind i Staden, og Muren faldt paa syv og tyve Tusinde Mænd, som vare blevne tilovers; og Benhadad flyede og kom i Staden, fra et Kammer til et andet.',
        31: 'Da sagde hans Tjenere til ham: Kære, se, vi have hørt, at Israels Konger ere naadige Konger; kære, lader os lægge Sække om vore Lænder og Reb om vore Hoveder og gaa ud til Israels Konge, maaske han lader din Sjæl leve.',
        32: 'Og de bandt Sække om deres Lænder og Reb om deres Hoveder, og de kom til Israels Konge og sagde: Benhadad, din Tjener siger: Kære, lad min Sjæl leve; og han sagde: Lever han endnu? han er min Broder.',
        33: 'Og Mændene udlagde sig det til det gode og skyndte sig med at faa ham til at sige, om det var hans Alvor, og de sagde: Benhadad er din Broder; og han sagde: Gaar ind, henter ham hid; da gik Benhadad ud til ham, og han lod ham stige op paa Vognen.',
        34: 'Og Benhadad sagde til ham: Jeg vil give dig igen de Stæder, som min Fader tog fra din Fader, og du maa anlægge dig Gader i Damaskus, ligesom min Fader anlagde i Samaria; og jeg, sagde Akab, vil med den Pagt lade dig fare. Saa gjorde han en Pagt med ham og lod ham fare.',
        35: 'Og en Mand af Profeternes Børn sagde til sin Næste ved Herrens Ord: Kære, slaa mig; men Manden vægrede sig ved at slaa ham.',
        36: 'Da sagde han til ham: Fordi du ikke adlød Herrens Røst, se, da skal en Løve slaa dig, naar du gaar fra mig; og han gik fra ham, og en Løve traf ham og slog ham.',
        37: 'Og han traf en anden Mand og sagde: Kære, slaa mig; og Manden slog ham haardt og saarede ham.',
        38: 'Da gik Profeten og stod for Kongen paa Vejen og gjorde sig ukendelig med et Klæde over sine Øjne.',
        39: 'Og det skete, da Kongen drog forbi, at han raabte til Kongen og sagde: Din Tjener var dragen ud midt i Krigen, og se, en Mand veg af Vejen og førte en Mand til mig og sagde: Forvar denne Mand; dersom han savnes, da skal dit Liv være i Stedet for hans Liv, eller du skal betale et Centner Sølv.',
        40: 'Og det skete, der din Tjener havde at gøre her og der, da var han ikke mere der; og Israels Konge sagde til ham: Saa er din Dom, du har selv fældet den.',
        41: 'Da skyndte han sig og tog Klædet bort fra sine Øjne, og Israels Konge kendte ham, at han var en af Profeterne.',
        42: 'Og han sagde til ham: Saa sagde Herren: Fordi du slap den Mand, som jeg har sat i Band, af din Haand, da skal din Sjæl være i Stedet for hans Sjæl, og dit Folk i Stedet for hans Folk.',
        43: 'Saa drog Israels Konge til sit Hus, ilde tilfreds og vred; og han kom til Samaria.',
    },
    21: {
        1: 'Og det skete efter disse Handeler, at Jisreeliteren Naboth havde en Vingaard, som var i Jisreel ved Akabs Palads, Kongens i Samaria.',
        2: 'Og Akab talede til Naboth og sagde: Giv mig din Vingaard, at den maa være mig til en Urtehave, efterdi den er nær ved mit Hus, og jeg vil give dig en Vingaard for den, som er bedre end denne; eller om dig godt synes, vil jeg give dig Penge for den, saa meget som den er værd.',
        3: 'Og Naboth sagde til Akab: Herren lade det være langt fra mig, at jeg skulde give dig mine Fædres Arv.',
        4: 'Da kom Akab ilde tilfreds og vred til sit Hus for det Ords Skyld, søm Jisreeliteren Naboth havde talt til ham og sagt: Jeg vil ikke give dig mine Fædres Arv; og han lagde sig paa sin Seng og vendte sit Ansigt omkring og aad ikke Brød.',
        5: 'Da kom Jesabel, hans Hustru, til ham, og hun sagde til ham: Hvad er det for noget, at din Aand er saa ilde tilfreds, at du ikke æder Brød?',
        6: 'Og han sagde til hende: Fordi jeg talte til Jisreeliteren Naboth og sagde til ham: Giv mig din Vingaard for Penge, eller om du har Lyst dertil, da vil jeg give dig en anden Vingaard for den, og han sagde: Jeg vil ikke give dig min Vingaard.',
        7: 'Da sagde Jesabel, hans Hustru, til ham: Du, jo, du skulde nu have Kongemagt over Israel! staa op, æd Brød og lad dit Hjerte være vel til Mode, jeg vil give dig Jisreeliteren Naboths Vingaard.',
        8: 'Og hun skrev Breve i Akabs Navn og forseglede dem med hans Signet, og hun sendte Brevene til de ældste og til de ypperste, som vare i hans Stad, og som boede ved Naboth.',
        9: 'Og hun skrev i Brevene og sagde: Lader udraabe en Faste, og sætter Naboth øverst iblandt Folket!',
        10: 'Og sætter to Mænd, Belials Børn, tværs overfor ham, som skulle vidne imod ham og sige: Du har bandet Gud og Kongen; og fører ham ud og stener ham, at han dør.',
        11: 'Og de ældste Mænd og ypperste i hans Stad, som boede i hans Stad, gjorde, ligesom Jesabel havde ladet sige til dem, ligesom der var skrevet i Brevene, som hun havde sendt til dem.',
        12: 'Delode udraabe en Faste og satte Naboth øverst iblandt Folket.',
        13: 'Og de to Mænd, de Belials Børn, kom og satte sig tværs overfor ham, og de Belials Mænd vidnede imod Naboth for Folket og sagde: Naboth bandede Gud og Kongen; og de førte ham ud uden for Staden og stenede ham med Stene, at han døde.',
        14: 'Og de sendte til Jesabel og lode sige: Naboth er stenet og er død.',
        15: 'Og det skete, der Jesabel hørte, at Naboth var stenet og var død, da sagde Jesabel til Akab: Staa op, tag til Eje Jisreeliteren Naboths Vingaard, som han vægrede sig ved at give dig for Penge; thi Naboth lever ikke, men er død.',
        16: 'Og det skete, der Akab hørte, at Naboth var død, da stod Akab op at gaa ned i Jisreeliteren Naboths Vingaard for at tage den til Eje.',
        17: 'Og Herrens Ord skete til Thisbiteren Elias og sagde:',
        18: 'Staa op, gak ned imod Akab, Israels Konge, som er i Samaria; se, han er i Naboths Vingaard, hvorhen han er gaaet ned for at tage den til Ejendom.',
        19: 'Og du skal tale til ham og sige: Saaledes sagde Herren: Har du baade myrdet og tilmed taget en Ejendom? Fremdeles skal du tale til ham og sige: Saa siger Herren: Paa det Sted, hvor Hundene slikkede Naboths Blod, skulle Hundene slikke dit Blod, ja ogsaa dit.',
        20: 'Og Akab sagde til Elias: Har du fundet mig, min Fjende? Og han sagde: Jeg har fundet dig, fordi du har solgt dig selv til at gøre det onde for Herrens Øjne.',
        21: 'Se, jeg vil føre Ulykke over dig og borttage dine Efterkommere og udrydde af alt Akabs Hus enhver af Mandkøn og den bundne og den løsladte i Israel.',
        22: 'Og jeg vil gøre dit Hus som Jeroboams, Nebats Søns, Hus, og som Baesas, Ahias Søns, Hus, for den Opirrelses Skyld, som du har opirret mig med, og fordi du kom Israel til at synde.',
        23: 'Og om Jesabel har Herren ogsaa talt og sagt: Hundene skulle æde Jesabel inden Jisreels Mure.',
        24: 'Hvo som dør i Staden af Akabs Hus, skulle Hundene æde, og hvo som dør paa Marken, skulle Fuglene under Himmelen æde.',
        25: 'Dog var der ingen som Akab, der havde solgt sig selv til at gøre det onde for Herrens Øjne, fordi hans Hustru Jesabel tilskyndte ham;',
        26: 'og han handlede saare vederstyggeligt, idet han vandrede efter de stygge Afguder, aldeles ligesom Amoriterne gjorde, hvilke Herren fordrev for Israels Børns Ansigt.',
        27: 'Og det skete, der Akab hørte disse Ord, da sønderrev han sine Klæder og lagde Sæk om sin Krop og fastede, og han laa i Sæk og gik sagtelig.',
        28: 'Og Herrens Ord skete til Thisbiteren Elias og sagde:',
        29: 'Har du set, at Akab har ydmyget sig for mit Ansigt? fordi han har ydmyget sig for mit Ansigt, vil jeg ikke lade det onde komme i hans Dage; i hans Søns Dage vil jeg føre det onde over hans Hus.',
    },
    22: {
        1: 'Og de sade stille tre Aar; der var ingen Krig imellem Syrerne og Israel.',
        2: 'Men det skete i det tredje Aar, da drog Josafat, Judas Konge, ned til Israels Konge.',
        3: 'Og Israels Konge sagde til sine Tjenere: Vide I, at Ramoth i Gilead hører os til? og vi tie stille om at tage den tilbage af Syriens Konges Haand!',
        4: 'Derefter sagde han til Josafat: Vil du drage med mig til Krig imod Ramoth i Gilead? og Josafat sagde til Israels Konge: Jeg vil være som du, mit Folk skal være som dit Folk, mine Heste som dine Heste.',
        5: 'Fremdeles sagde Josafat til Israels Konge: Kære, adspørg i Dag Herrens Ord!',
        6: 'Da samlede Israels Konge Profeterne, ved fire Hundrede Mænd, og sagde til dem: Skal jeg drage til Krig imod Ramoth i Gilead eller lade det være? og de sagde: Drag op, og Herren skal give den i Kongens Haand.',
        7: 'Men Josafat sagde: Er her ikke endnu en Herrens Profet, at vi kunde spørge ham ad?',
        8: 'Og Israels Konge sagde til Josafat: Her er endnu een Mand, ved hvem man kan adspørge Herren, men jeg hader ham, fordi han spaar ikke godt over mig, men ondt, det er Mika, Jimlas Søn; og Josafat sagde: Kongen sige ikke saa!',
        9: 'Da kaldte Israels Konge ad en af Kammertjenerne og sagde: Hent hurtigt Mika, Jimlas Søn!',
        10: 'Og Israels Konge og Josafat, Judas Konge, sade hver paa sin Trone, iførte Kongedragt, paa en fri Plads ved Indgangen til Samarias Port, og alle Profeterne spaaede for deres Ansigt.',
        11: 'Og Zedekia, Knaanas Søn, havde gjort sig Jernhorn, og han sagde: Saaledes sagde Herren: Med disse skal du stange Syrerne, indtil de aldeles udryddes.',
        12: 'Og alle Profeterne spaaede saaledes og sagde: Drag op imod Ramoth i Gilead og vær lykkelig, og Herren skal give den i Kongens Haand.',
        13: 'Og Budet, som var gaaet bort for at kalde paa Mika, talte til ham sigende: Kære, se, Profeternes Ord ere som af een Mund gunstige for Kongen; kære, lad dit Ord være ligesom Ordet af en af dem og tal gunstigt!',
        14: 'Da sagde Mika: Saa vist som Herren lever, det som Herren siger mig, det vil jeg tale.',
        15: 'Og han kom til Kongen, og Kongen sagde til ham: Mika! skulle vi drage imod Ramoth i Gilead til Krig eller lade være? Og han sagde til ham: Drag op og vær lykkelig, og Herren skal give den i Kongens Haand.',
        16: 'Og Kongen sagde til ham: Hvor mange Gange skal jeg besværge dig, at du intet siger mig uden Sandheden i Herrens Navn?',
        17: 'Da sagde han: Jeg saa al Israel adspredt paa Bjergene ligesom Faarene, der ingen Hyrde have; og Herren sagde: Disse have ingen Herre, lad dem vende tilbage hver til sit Hus med Fred!',
        18: 'Da sagde Israels Konge til Josafat: Har jeg ikke sagt dig: Han spaar mig ikke godt, men ondt?',
        19: 'Og han sagde: Hør derfor Herrens Ord: Jeg saa Herren sidde paa sin Trone, og al Himmelens Hær staaende hos ham ved hans højre og ved hans venstre Side.',
        20: 'Og Herren sagde: Hvo vil overtale Akab, at han skal drage op og falde ved Ramoth i Gilead? og den ene sagde saa, og den anden sagde saa.',
        21: 'Da gik en Aand ud og stod for Herrens Ansigt og sagde: Jeg vil overtale ham; og Herren sagde til ham: Hvormed?',
        22: 'Og han sagde: Jeg vil gaa ud og være en løgnagtig Aand i alle hans Profeters Mund; og han sagde: Du skal overtale ham, ja ogsaa formaa det; gak ud og gør saa!',
        23: 'Og nu, se, Herren har givet en løgnagtig Aand i alle disse dine Profeters Mund; men Herren har talt ondt over dig.',
        24: 'Da gik Zedekia, Knaanas Søn, frem og slog Mika paa Kinden og sagde: Hvorledes? er Herrens Aand gaaet over fra mig for at tale med dig?',
        25: 'Og Mika sagde: Se, du skal se det paa den Dag, naar du gaar ind fra et Kammer til et andet for at skjule dig.',
        26: 'Da sagde Israels Konge: Tag Mika og før ham tilbage til Amon, Stadens Befalingsmand, og til Joas, Kongens Søn.',
        27: 'Og du skal sige: Saa siger Kongen: Sætter denne i Fængsels Hus og bespiser ham med Trængsels Brød og Trængsels Vand, indtil jeg kommer med Fred.',
        28: 'Og Mika sagde: Dersom du kommer tilbage med Fred, da har Herren ikke talt ved mig; og han sagde: Hører, I Folk alle sammen!',
        29: 'Saa drog Israels Konge og Josafat, Judas Konge, op imod Ramoth i Gilead.',
        30: 'Og Israels Konge sagde til Josafat: Jeg vil forklæde mig og saa gaa i Kampen, men tag du dine egne Klæder paa; og Israels Konge forklædte sig og gik i Slaget.',
        31: 'Men Kongen af Syrien bød sine to og tredive øverste for Vognene og sagde: I skulle ikke stride imod liden eller stor, uden imod Israels Konge alene.',
        32: 'Og det skete, der de øverste for Vognene saa Josafat, da sagde de: Han er visselig Israels Konge, og de bøjede af for at stride imod ham. Da raabte Josafat.',
        33: 'Og det skete, der de øverste for Vognene saa, at han ikke var Israels Konge, da vendte de tilbage fra ham.',
        34: 'Og en Mand spændte Buen paa Lykke og Fromme og skød Israels Konge mellem Remmene og Panseret; da sagde denne til sin Køresvend: Vend din Haand om og før mig ud af Hæren; thi jeg er saaret.',
        35: 'Og Kampen tog til paa den samme Dag, og Kongen blev holdt staaende i Vognen over for Syrerne, og han døde om Aftenen, og Blodet flød af Saaret midt i Vognen.',
        36: 'Og man udraabte igennem Lejren, der Solen gik ned, og sagde: Hver gaa til sin Stad og hver til sit Land!',
        37: 'Saa døde Kongen og blev ført til Samaria, og de begrove Kongen i Samaria.',
        38: 'Og man skyllede Vognen ved Samarias Dam; og Hundene slikkede hans Blod, hvor Skøgerne badede sig, efter Herrens Ord, som han havde talt.',
        39: 'Men det øvrige af Akabs Handeler, og alt det han gjorde, og om det Elfenbens Hus, som han byggede, og om alle Stæderne, som han byggede, er det ikke skrevet i Israels Kongers Krønikers Bog?',
        40: 'Og Akab laa med sine Fædre, og Ahasia, hans Søn, blev Konge i hans Sted.',
        41: 'Og Josafat, Asas Søn, blev Konge over Juda i Akabs, Israels Konges, fjerde Aar.',
        42: 'Josafat var fem og tredive Aar gammel, der han blev Konge, og regerede fem og tyve Aar i Jerusalem, og hans Moders Navn var Asuba, Silhis Datter.',
        43: 'Og han vandrede i alle sin Fader Asas Veje og veg ikke derfra, men gjorde det, som var ret for Herrens Øjne.',
        44: 'Dog bleve Højene ikke borttagne; Folket ofrede endnu og gjorde Røgelse paa Højene.',
        45: 'Og Josafat holdt Fred med Israels Konge.',
        46: 'Men det øvrige af Josafats Handeler og hans Magt, hvilken han skaffede sig, og hvorledes han har stridt, er det ikke skrevet i Judas Kongers Krønikers Bog?',
        47: 'Og de øvrige af Skørlevnerne, som vare blevne tilbage fra Asas, hans Faders, Dage, borttog han af Landet.',
        48: 'Og der var ingen Konge i Edom; men en Befalingsmand var Konge.',
        49: 'Og Josafat havde ti Tharsisskibe, som skulde drage til Ofir efter Guld; men de droge ikke derhen, thi Skibene bleve sønderslagne i Ezion-Geber.',
        50: 'Da sagde Ahasia, Akabs Søn, til Josafat: Lad mine Tjenere fare med dine Tjenere paa Skibene; men Josafat vilde ikke.',
        51: 'Og Josafat laa med sine Fædre og blev begraven med sine Fædre i Davids, sin Faders, Stad; og Joram, hans Søn, blev Konge i hans Sted.',
        52: 'Ahasia, Akabs Søn, blev Konge over Israel i Samaria udi Josafats, Judas Konges, syttende Aar og var Konge over Israel to Aar.',
        53: 'Og han gjorde det, som ondt var for Herrens Øjne, og vandrede i sin Faders Vej og i sin Moders Vej og i Jeroboams, Nebats Søns, Vej, hans, som kom Israel tir at synde. Og han tjente Baal og tilbad ham og opirrede Herren, Israels Gud, alt ligesom hans Fader gjorde.',
    },
}
